INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C3','kor',1,2,'u1',5,'마음을 나타내는 흉내 내는 말 — 「내 마음을 보여 줄까?」의 꽁꽁·반짝반짝·찌지직·우르릉 쾅쾅이 나타내는 마음 읽기',ARRAY['2국05-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C4','kor',1,2,'u1',7,'기분을 나타내는 말 — 상황에 어울리는 기분 말 고르기, 기분 말과 물건 이름 구별',ARRAY['2국01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
