INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u1-C6','kor',1,2,'u1',13,'문장의 짜임 — 누가·무엇을·어찌하다 순서로 뜻이 통하는 문장 만들기',ARRAY['2국04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X01','kor',1,'u1',ARRAY['K1-2-u1-C1']::text[],'물건·사람·곳 이름을 흉내 내는 말로 고른다 (들판·나뭇잎을 흉내 내는 말로)','「소리가 나요? 모양이 보여요?」 두 질문으로 걸러 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X02','kor',1,'u1',ARRAY['K1-2-u1-C1']::text[],'소리를 흉내 낸 말과 모양을 흉내 낸 말을 뒤바꾼다 (개굴개굴을 모양으로)','말을 입으로 내 보고 「귀로 들은 것인지, 눈으로 본 것인지」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X03','kor',1,'u1',ARRAY['K1-2-u1-C2']::text[],'문장 상황과 어긋나는 흉내 내는 말을 넣는다 (눈이 꼬르륵 쌓여요)','흉내 내는 말을 뺀 문장부터 읽고 「무엇이 어떻게 하는 장면인지」 그려 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X04','kor',1,'u1',ARRAY['K1-2-u1-C2']::text[],'흉내 내는 말은 문장을 길게 만드는 것이라고 여긴다 (실감·장면이 떠오르는 효과를 모름)','흉내 내는 말이 있는 문장과 없는 문장을 나란히 읽고 무엇이 보이는지 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X05','kor',1,'u1',ARRAY['K1-2-u1-C3']::text[],'물건에서 나는 소리 흉내를 마음을 나타낸 말로 고른다 (딸랑딸랑을 마음으로)','「누구 마음이 그런 거예요?」 — 마음의 임자를 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X06','kor',1,'u1',ARRAY['K1-2-u1-C3']::text[],'흉내 내는 말이 나타내는 마음을 다르게 읽는다 (부글부글을 신난 마음으로)','그 말이 나온 앞뒤 일을 다시 읽고 좋은 일인지 속상한 일인지 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X07','kor',1,'u1',ARRAY['K1-2-u1-C4']::text[],'상황과 어긋나는 기분 말을 고른다 (도움을 받았는데 화나요)','「나라면 어떤 마음이 들까」 상황을 몸으로 떠올려 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X08','kor',1,'u1',ARRAY['K1-2-u1-C4']::text[],'물건 이름·하는 일을 기분을 나타내는 말로 고른다 (필통·달리기를 기분 말로)','기분 말은 「마음이 ~해요」로 바꿔 말할 수 있는지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X09','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'상대를 탓하는 말을 기분 말하기로 여긴다 (너 때문에 다 망쳤어)','말의 첫 낱말이 「너」인지 「나」인지 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X10','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'「나」로 시작만 하면 된다고 여겨 있었던 일이나 기분을 빠뜨리거나 탓하는 말을 넣는다 (나는 네가 미워)','「나는 (있었던 일)해서 (기분)했어」 틀에 한 칸씩 채워 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X11','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'기분을 말하는 차례를 모른다 (큰 소리부터 내기·아무 말도 안 하기)','① 무슨 일 ② 내 기분 ③ 듣는 사람 ④ 「나」로 말하기 네 걸음 손가락으로 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X12','kor',1,'u1',ARRAY['K1-2-u1-C5','K1-2-u1-C4']::text[],'기분을 말할 필요를 못 느낀다 — 좋은 기분은 말 안 해도 된다고 여기거나(칭찬을 받고도 시큰둥), 기분을 말하면 무엇이 좋은지 모른다','고마운 마음도 말로 전하면 상대 기분이 어떻게 되는지 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X13','kor',1,'u1',ARRAY['K1-2-u1-C6']::text[],'누가·무엇을 자리를 바꿔 뜻이 뒤집힌 문장을 고른다 (도토리가 다람쥐를 먹습니다)','그림을 보며 「누가 하는 일인지」 손가락으로 짚고 첫 낱말 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X14','kor',1,'u1',ARRAY['K1-2-u1-C6']::text[],'무엇을 과 어울리지 않는 어찌하다를 고른다 (우산을 마십니다)','끝 낱말을 넣어 몸으로 해 보게 하기 — 할 수 없는 일이면 어긋난 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u1-X15','kor',1,'u1',ARRAY['K1-2-u1-C5']::text[],'낱말의 뜻을 겉소리로 짐작한다 (「굳다」를 단단한 물건으로, 「나도 모르게」를 일부러로)','그 낱말이 나온 앞뒤 줄을 다시 읽고 어떤 마음·장면인지 말로 바꿔 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#1','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 7쪽 생각 열기 — 입을 활짝 벌리고 환하게 웃는 아이예요. 아이의 기분은 어떠할까요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 7쪽 생각 열기 — 입을 활짝 벌리고 환하게 웃는 아이예요. 아이의 기분은 어떠할까요?","options":[{"t":"행복해요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X07"},{"t":"속상해요","mis":"K1-2-u1-X07"}],"explanation":["환하게 웃는 얼굴은 행복한 기분이에요.","무섭거나 속상하면 활짝 웃지 않아요.","생일 선물을 받았을 때처럼 활짝 웃었던 때를 떠올려 봐요."],"asset":{"type":"scene","icon":"😄","text":"활짝 웃는 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#2','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C2',1,'mc','auto','『국어』 8쪽 — 노래를 들으며 웃는 모습을 더 실감 나게 말한 것은 어느 것인가요?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":2,"concept":"K1-2-u1-C2","difficulty":1,"kind":"mc","stem":"『국어』 8쪽 — 노래를 들으며 웃는 모습을 더 실감 나게 말한 것은 어느 것인가요?","options":[{"t":"친구가 활짝 웃고 있어요.","correct":true},{"t":"친구가 웃고 있어요.","mis":"K1-2-u1-X04"},{"t":"친구가 있어요.","mis":"K1-2-u1-X04"}],"explanation":["「활짝」을 넣으면 웃는 모습이 눈앞에 떠올라요.","흉내 내는 말이 없으면 어떻게 웃는지 알 수 없어요.","흉내 내는 말을 넣어 장면을 이야기해요."],"asset":{"type":"scene","icon":"🎶😄","text":"노래를 들으며 웃어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#3','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 9쪽 2번 ㉮ — 놀이공원에서 노는 장면에 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 9쪽 2번 ㉮ — 놀이공원에서 노는 장면에 어울리는 기분을 나타내는 말은?","options":[{"t":"신나요","correct":true},{"t":"속상해요","mis":"K1-2-u1-X07"},{"t":"걱정돼요","mis":"K1-2-u1-X07"}],"explanation":["놀이공원에서 놀면 신나고 즐거워요.","속상하거나 걱정되는 일이 아니에요.","기분 나무에서 어울리는 열매를 찾아요."],"asset":{"type":"scene","icon":"🎡🎠","text":"놀이공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#4','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 9쪽 2번 ㉯ — 병원에 누워 있는 장면에 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 9쪽 2번 ㉯ — 병원에 누워 있는 장면에 어울리는 기분을 나타내는 말은?","options":[{"t":"속상해요","correct":true},{"t":"신나요","mis":"K1-2-u1-X07"},{"t":"뿌듯해요","mis":"K1-2-u1-X07"}],"explanation":["아파서 병원에 누워 있으면 속상하고 걱정돼요.","신나거나 뿌듯한 일이 아니에요.","그 자리의 나를 떠올려요."],"asset":{"type":"scene","icon":"🏥🛏️","text":"병원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#5','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'mc','auto','『국어』 9쪽 2번 ㉰ — 친구에게 선물을 받는 장면에 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":5,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"『국어』 9쪽 2번 ㉰ — 친구에게 선물을 받는 장면에 어울리는 기분을 나타내는 말은?","options":[{"t":"고마워요","correct":true},{"t":"화나요","mis":"K1-2-u1-X07"},{"t":"심심해요","mis":"K1-2-u1-X07"}],"explanation":["선물을 받으면 기쁘고 고마워요.","화나거나 심심한 일이 아니에요.","내가 선물을 받았다고 생각해 봐요."],"asset":{"type":"scene","icon":"🎁🙂","text":"선물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#6','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'mc','auto','기분 나무에 열린 말 가운데 「기분을 나타내는 말」이 아닌 것은?',ARRAY['K1-2-u1-X08']::text[],false,'{"seq":6,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"기분 나무에 열린 말 가운데 「기분을 나타내는 말」이 아닌 것은?","options":[{"t":"책가방","correct":true},{"t":"궁금해요","mis":"K1-2-u1-X08"},{"t":"부러워요","mis":"K1-2-u1-X08"}],"explanation":["책가방은 물건 이름이라 기분이 아니에요.","궁금해요·부러워요는 마음이 어떠한지 알려 주는 말이에요.","「마음이 ○○해요」로 바꿀 수 있는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#7','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'match','auto','장면과 어울리는 기분을 나타내는 말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"장면과 어울리는 기분을 나타내는 말을 이어 보세요.","pairs":[{"l":"놀이공원에서 놀아요","r":"즐거워요"},{"l":"병원에 누워 있어요","r":"걱정돼요"},{"l":"친구가 선물을 줬어요","r":"기뻐요"}],"mis":"K1-2-u1-X07","explanation":["『국어』 9쪽 2번 세 장면이에요.","놀이공원은 즐겁고, 병원은 걱정되고, 선물은 기뻐요.","장면마다 나라면 어떤 마음일지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
