INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#9','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C4',2,'ox','auto','같은 장면을 보고도 사람마다 느끼는 기분이 다를 수 있어요.',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":9,"concept":"K1-2-u1-C4","difficulty":2,"kind":"ox","stem":"같은 장면을 보고도 사람마다 느끼는 기분이 다를 수 있어요.","answer":"O","reason_options":[{"t":"친구가 말한 기분을 들어 보면 나와 다를 수 있으니까","correct":true},{"t":"같은 장면이면 기분도 꼭 같아야 하니까","mis":"K1-2-u1-X07"}],"mis":"K1-2-u1-X07","explanation":["같은 상황에서도 사람마다 느끼는 기분이 다를 수 있어요.","기분에는 맞고 틀린 것이 없어요.","친구 말을 듣고 내 기분과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_basic#10','kor',1,2,'u1','L01','g1_2_kor_u1_L01_basic','lesson_basic','K1-2-u1-C5',3,'mc','auto','『국어』 9쪽 3번처럼 자신이 평소에 기분을 나타내는 말을 떠올려 써 붙이면 무엇이 좋을까요?',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"『국어』 9쪽 3번처럼 자신이 평소에 기분을 나타내는 말을 떠올려 써 붙이면 무엇이 좋을까요?","options":[{"t":"내 마음을 더 실감 나게 전할 수 있어요","correct":true},{"t":"달리기가 빨라져요","mis":"K1-2-u1-X12"},{"t":"글씨가 예뻐져요","mis":"K1-2-u1-X12"}],"explanation":["흉내 내는 말이나 기분을 나타내는 말을 넣으면 더 실감 나게 말할 수 있어요.","달리기나 글씨와는 상관없어요.","말하지 않으면 남이 내 마음을 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#1','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C2',2,'mc','auto','『국어』 8쪽 그림 — 노래를 들으며 웃는 장면에 어울리는 흉내 내는 말은?',ARRAY['K1-2-u1-X03']::text[],false,'{"seq":1,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"『국어』 8쪽 그림 — 노래를 들으며 웃는 장면에 어울리는 흉내 내는 말은?","options":[{"t":"활짝","correct":true},{"t":"꼬르륵","mis":"K1-2-u1-X03"},{"t":"쨍그랑","mis":"K1-2-u1-X03"}],"explanation":["「활짝 웃는다」고 하면 더 실감 나요.","꼬르륵은 배 소리, 쨍그랑은 깨지는 소리예요.","장면을 먼저 그려 봐요."],"asset":{"type":"scene","icon":"🎶😄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
