INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#4','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',3,'mc','auto','같은 놀이공원인데 한 친구는 「신나요」, 다른 친구는 「무서워요」라고 해요. 왜 그럴까요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":3,"kind":"mc","stem":"같은 놀이공원인데 한 친구는 「신나요」, 다른 친구는 「무서워요」라고 해요. 왜 그럴까요?","options":[{"t":"사람마다 느끼는 기분이 다를 수 있어서","correct":true},{"t":"한 친구가 틀리게 느껴서","mis":"K1-2-u1-X07"},{"t":"놀이공원이 너무 커서","mis":"K1-2-u1-X07"}],"explanation":["같은 상황에서도 사람마다 느끼는 기분이 달라요.","기분에는 맞고 틀린 것이 없어요.","서로 기분을 말해 주면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#5','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',3,'match','auto','장면과 그때 드는 기분을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C4","difficulty":3,"kind":"match","stem":"장면과 그때 드는 기분을 이어 보세요.","pairs":[{"l":"생일 선물을 받았어요","r":"기뻐요"},{"l":"친구가 오랜만에 찾아왔어요","r":"반가워요"},{"l":"아끼던 장난감이 망가졌어요","r":"속상해요"},{"l":"어려운 일을 혼자 해냈어요","r":"뿌듯해요"}],"mis":"K1-2-u1-X07","explanation":["선물은 기쁘고, 오랜만에 만나면 반가워요.","망가지면 속상하고, 혼자 해내면 뿌듯해요.","기분 나무의 열매를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
