INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#7','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C5',3,'ox','auto','기분을 말로 하면 서로 더 잘 지낼 수 있어요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":3,"kind":"ox","stem":"기분을 말로 하면 서로 더 잘 지낼 수 있어요.","answer":"O","reason_options":[{"t":"내 마음을 알면 상대가 이해하거나 도와줄 수 있으니까","correct":true},{"t":"기분을 말하면 싸움만 되니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["마음을 말로 알려 주면 상대가 이해할 수 있어요.","말하는 방법이 중요한 거예요.","듣는 사람을 생각하며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#8','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',4,'sa','auto','친구가 선물을 주었을 때 드는 기분을 나타내는 말을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u1-C4","difficulty":4,"kind":"sa","stem":"친구가 선물을 주었을 때 드는 기분을 나타내는 말을 한 낱말로 쓰세요.","answer":["기뻐요","기뻐","기쁘다","기뻤어요","기뻤어","기쁨","고마워요","고마워","고맙다","고마웠어요","고마웠어","행복해요","행복해","행복했어요"],"explanation":["선물을 받으면 기쁘고 고마워요.","속상하거나 화나는 일이 아니에요.","기분 나무에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#9','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C4',4,'essay','teacher','『국어』 9쪽 3번 — 자신은 평소에 어떤 말로 기분을 표현하는지 떠올려 한 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C4","difficulty":4,"kind":"essay","stem":"『국어』 9쪽 3번 — 자신은 평소에 어떤 말로 기분을 표현하는지 떠올려 한 가지 쓰세요.","answer_guide":{"answer":"예: 신나요 / 고마워요 / 속상해요 / 심심해요 — 마음이 어떠한지 알려 주는 말이면 맞아요.","scoring_points":["기분을 나타내는 말인가","물건·장소 이름이 아닌가","자신이 평소 쓰는 말인가"]},"explanation":["마음이 어떠한지 알려 주는 말을 써요.","물건 이름이나 하는 일은 기분이 아니에요.","기분 나무 열매를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L01_challenge#10','kor',1,2,'u1','L01','g1_2_kor_u1_L01_challenge','lesson_challenge','K1-2-u1-C2',4,'essay','teacher','「친구가 웃어요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"「친구가 웃어요.」에 흉내 내는 말을 넣어 더 실감 나게 바꿔 쓰세요.","answer_guide":{"answer":"예: 친구가 활짝 웃어요. / 친구가 깔깔 웃어요. — 웃는 모양이나 소리에 어울리면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","웃는 장면과 어울리는가","문장이 자연스러운가"]},"explanation":["활짝·깔깔처럼 웃는 모양이나 소리를 넣어요.","쨍그랑처럼 상관없는 소리는 어긋나요.","『국어』 8쪽 친구들의 말을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#1','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','『국어』 10쪽 글을 읽고 답하세요. 구름이 어떻게 떠 있나요?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 10쪽 글을 읽고 답하세요. 구름이 어떻게 떠 있나요?","options":[{"t":"둥실둥실","correct":true},{"t":"가을 하늘에","mis":"K1-2-u1-X01"},{"t":"구름이","mis":"K1-2-u1-X01"}],"explanation":["구름은 둥실둥실 떠 있어요.","가을 하늘과 구름은 흉내 내는 말이 아니에요.","모양을 나타낸 말을 찾아요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#2','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','『국어』 10쪽 글에서 단풍나무잎의 움직임을 흉내 낸 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 10쪽 글에서 단풍나무잎의 움직임을 흉내 낸 말은?","options":[{"t":"살랑살랑","correct":true},{"t":"가을바람","mis":"K1-2-u1-X01"},{"t":"움직입니다","mis":"K1-2-u1-X01"}],"explanation":["잎이 가을바람에 살랑살랑 움직여요.","가을바람은 이름, 움직입니다는 하는 일이에요.","모양을 옮긴 말을 찾아요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#3','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','『국어』 10쪽 글에서 고양이들이 낸 소리는?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":3,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 10쪽 글에서 고양이들이 낸 소리는?","options":[{"t":"야옹","correct":true},{"t":"귀여운","mis":"K1-2-u1-X01"},{"t":"반겨","mis":"K1-2-u1-X01"}],"explanation":["고양이들이 야옹 소리를 내며 반겨 줘요.","귀여운·반겨는 소리가 아니에요.","입으로 내 보면 소리인지 알 수 있어요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#4','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',1,'mc','auto','「둥실둥실」, 「야옹」처럼 모양이나 소리를 나타내는 말을 무엇이라고 하나요?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":4,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"「둥실둥실」, 「야옹」처럼 모양이나 소리를 나타내는 말을 무엇이라고 하나요?","options":[{"t":"흉내 내는 말","correct":true},{"t":"기분을 나타내는 말","mis":"K1-2-u1-X01"},{"t":"이름을 나타내는 말","mis":"K1-2-u1-X01"}],"explanation":["모양이나 소리를 나타내는 말을 흉내 내는 말이라고 해요.","기분을 나타내는 말은 기뻐요·슬퍼요 같은 말이에요.","『국어』 10쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#5','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',2,'match','auto','『국어』 11쪽 2번 — 그림에 어울리는 흉내 내는 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"『국어』 11쪽 2번 — 그림에 어울리는 흉내 내는 말을 선으로 이어 보세요.","pairs":[{"l":"🕰️ 시계","r":"째깍째깍"},{"l":"🐰 토끼","r":"깡충깡충"},{"l":"☁️ 구름","r":"둥실둥실"},{"l":"😆 웃는 아이","r":"깔깔"}],"mis":"K1-2-u1-X03","explanation":["시계는 째깍째깍, 토끼는 깡충깡충이에요.","구름은 둥실둥실, 웃는 아이는 깔깔이에요.","소리인지 모양인지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#6','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',2,'mc','auto','「깔깔」, 「째깍째깍」은 어떤 흉내 내는 말인가요?',ARRAY['K1-2-u1-X02','K1-2-u1-X01']::text[],false,'{"seq":6,"concept":"K1-2-u1-C1","difficulty":2,"kind":"mc","stem":"「깔깔」, 「째깍째깍」은 어떤 흉내 내는 말인가요?","options":[{"t":"소리를 나타내는 말","correct":true},{"t":"모양을 나타내는 말","mis":"K1-2-u1-X02"},{"t":"이름을 나타내는 말","mis":"K1-2-u1-X01"}],"explanation":["깔깔·째깍째깍은 귀로 들은 소리를 옮긴 말이에요.","깡충깡충·둥실둥실이 모양을 나타내는 말이에요.","입으로 내 보면 소리인지 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#7','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C1',2,'mc','auto','「깡충깡충」, 「둥실둥실」은 어떤 흉내 내는 말인가요?',ARRAY['K1-2-u1-X02','K1-2-u1-X01']::text[],false,'{"seq":7,"concept":"K1-2-u1-C1","difficulty":2,"kind":"mc","stem":"「깡충깡충」, 「둥실둥실」은 어떤 흉내 내는 말인가요?","options":[{"t":"모양을 나타내는 말","correct":true},{"t":"소리를 나타내는 말","mis":"K1-2-u1-X02"},{"t":"기분을 나타내는 말","mis":"K1-2-u1-X01"}],"explanation":["깡충깡충·둥실둥실은 눈으로 본 모양을 옮긴 말이에요.","소리를 나타내는 말은 깔깔·째깍째깍이에요.","몸으로 따라 할 수 있으면 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
