INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_basic#10','kor',1,2,'u1','L03','g1_2_kor_u1_L03_basic','lesson_basic','K1-2-u1-C2',3,'mc','auto','『국어』 13쪽 4번 — 문장을 만들 때 흉내 내는 말을 사용하면 좋은 점은?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":3,"kind":"mc","stem":"『국어』 13쪽 4번 — 문장을 만들 때 흉내 내는 말을 사용하면 좋은 점은?","options":[{"t":"문장의 상황이 더 잘 떠오르고 실감 나요","correct":true},{"t":"문장이 짧아져요","mis":"K1-2-u1-X04"},{"t":"글씨가 예뻐져요","mis":"K1-2-u1-X04"}],"explanation":["「고양이가 야옹 하고 울었다.」가 「고양이가 울었다.」보다 실감 나요.","흉내 내는 말은 장면을 눈앞에 그려 줘요.","두 문장을 소리 내어 읽고 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#1','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',2,'mc','auto','『국어』 10쪽 글에서 자전거가 지나가는 모습을 흉내 낸 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":2,"kind":"mc","stem":"『국어』 10쪽 글에서 자전거가 지나가는 모습을 흉내 낸 말은?","options":[{"t":"씽씽","correct":true},{"t":"자전거","mis":"K1-2-u1-X01"},{"t":"지나갑니다","mis":"K1-2-u1-X01"}],"explanation":["아이가 자전거를 타고 씽씽 지나가요.","자전거는 이름, 지나갑니다는 하는 일이에요.","빠르게 지나가는 모습을 떠올려요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#2','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',2,'mc','auto','『국어』 13쪽 4번 — 「오리가 걸어간다.」보다 훨씬 재미있는 문장은?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":2,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"『국어』 13쪽 4번 — 「오리가 걸어간다.」보다 훨씬 재미있는 문장은?","options":[{"t":"오리가 뒤뚱뒤뚱 걸어간다.","correct":true},{"t":"오리가 저기로 걸어간다.","mis":"K1-2-u1-X04"},{"t":"오리가 걸어간다.","mis":"K1-2-u1-X04"}],"explanation":["뒤뚱뒤뚱을 넣으면 오리가 걷는 모습이 떠올라요.","흉내 내는 말이 없으면 모습이 그려지지 않아요.","교과서 13쪽 친구의 말을 떠올려요."],"asset":{"type":"scene","icon":"🦆"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#3','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',3,'error','auto','소리를 나타내는 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#4','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',3,'error','auto','「병아리가 울긋불긋 소리를 냅니다.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":4,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「병아리가 울긋불긋 소리를 냅니다.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"울긋불긋은 단풍 색깔 모양이라 병아리 소리와 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"병아리에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「소리를 냅니다」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["병아리는 삐악삐악 소리를 내요.","울긋불긋은 단풍이 물든 모양이에요.","『국어』 12쪽 3번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#5','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',3,'match','auto','『국어』 12쪽 3번 네 문장을 완성해 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C2","difficulty":3,"kind":"match","stem":"『국어』 12쪽 3번 네 문장을 완성해 보세요.","pairs":[{"l":"꽃이 ___ 피었습니다.","r":"활짝"},{"l":"매미가 ___ 울고 있습니다.","r":"맴맴"},{"l":"단풍이 ___ 물들었습니다.","r":"울긋불긋"},{"l":"병아리가 ___ 소리를 냅니다.","r":"삐악삐악"}],"mis":"K1-2-u1-X03","explanation":["꽃은 활짝, 매미는 맴맴이에요.","단풍은 울긋불긋, 병아리는 삐악삐악이에요.","그림의 상황을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#6','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',3,'mc','auto','『국어』 13쪽 5번 — 몸으로 표현할 수 있는 「모양을 나타내는 말」만 모은 것은?',ARRAY['K1-2-u1-X02']::text[],false,'{"seq":6,"concept":"K1-2-u1-C1","difficulty":3,"kind":"mc","stem":"『국어』 13쪽 5번 — 몸으로 표현할 수 있는 「모양을 나타내는 말」만 모은 것은?","options":[{"t":"폴짝폴짝 · 뒤뚱뒤뚱 · 엉금엉금","correct":true},{"t":"맴맴 · 야옹 · 꼬꼬댁","mis":"K1-2-u1-X02"},{"t":"깔깔 · 째깍째깍 · 삐악삐악","mis":"K1-2-u1-X02"}],"explanation":["폴짝폴짝·뒤뚱뒤뚱·엉금엉금은 모양이라 몸으로 표현해요.","맴맴·야옹·깔깔은 소리를 나타내는 말이에요.","몸으로 따라 할 수 있는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#7','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',3,'ox','auto','흉내 내는 말이 있는 문장은 없는 문장보다 상황을 더 잘 떠올릴 수 있어요.',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":7,"concept":"K1-2-u1-C2","difficulty":3,"kind":"ox","stem":"흉내 내는 말이 있는 문장은 없는 문장보다 상황을 더 잘 떠올릴 수 있어요.","answer":"O","reason_options":[{"t":"「야옹 하고 울었다」처럼 소리와 모습이 그려지니까","correct":true},{"t":"흉내 내는 말은 문장을 길게만 만드니까","mis":"K1-2-u1-X04"}],"mis":"K1-2-u1-X04","explanation":["흉내 내는 말이 있으면 장면이 눈앞에 떠올라요.","길게 만드는 게 아니라 실감 나게 해 줘요.","『국어』 13쪽 4번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#8','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',4,'sa','auto','『국어』 10쪽 글에 나온 흉내 내는 말 네 가지 가운데 한 가지를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u1-C1","difficulty":4,"kind":"sa","stem":"『국어』 10쪽 글에 나온 흉내 내는 말 네 가지 가운데 한 가지를 쓰세요.","answer":["둥실둥실","살랑살랑","야옹","씽씽"],"explanation":["둥실둥실·살랑살랑·야옹·씽씽이 흉내 내는 말이에요.","구름·단풍나무·고양이·자전거는 이름이에요.","모양이나 소리를 옮긴 말을 찾아요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#9','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C1',4,'sa','auto','「동물 농장」 노래에서 암탉이 내는 소리를 흉내 낸 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":4,"kind":"sa","stem":"「동물 농장」 노래에서 암탉이 내는 소리를 흉내 낸 말을 쓰세요.","answer":["꼬꼬댁","꼬꼬댁꼬꼬","꼬끼오","꼬꼬"],"explanation":["닭장 속 암탉은 꼬꼬댁이에요.","거위는 꽥꽥, 염소는 매, 송아지는 음매예요.","노래를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L03_challenge#10','kor',1,2,'u1','L03','g1_2_kor_u1_L03_challenge','lesson_challenge','K1-2-u1-C2',4,'essay','teacher','『국어』 13쪽 5번 — 「폴짝폴짝·쌩쌩·뒤뚱뒤뚱·엉금엉금·사뿐사뿐·덩실덩실·빙글빙글」 가운데 하나를 골라 문장을 만들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"『국어』 13쪽 5번 — 「폴짝폴짝·쌩쌩·뒤뚱뒤뚱·엉금엉금·사뿐사뿐·덩실덩실·빙글빙글」 가운데 하나를 골라 문장을 만들어 쓰세요.","answer_guide":{"answer":"예: 토끼가 폴짝폴짝 뛰어요. / 오리가 뒤뚱뒤뚱 걸어가요. — 고른 말과 어울리는 문장이면 맞아요.","scoring_points":["고른 흉내 내는 말이 들어갔는가","말과 상황이 어울리는가","문장이 자연스러운가"]},"explanation":["고른 말의 모양을 떠올려 어울리는 문장을 만들어요.","쌩쌩은 빠르게 달리는 모습, 엉금엉금은 느리게 기는 모습이에요.","몸으로 표현해 본 뒤 문장으로 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#1','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',1,'mc','auto','「내 마음을 보여 줄까?」 — 친구들 앞에서 노래를 부를 때 「나」의 기분은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":1,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음을 보여 줄까?」 — 친구들 앞에서 노래를 부를 때 「나」의 기분은?","options":[{"t":"떨렸다","correct":true},{"t":"신났다","mis":"K1-2-u1-X06"},{"t":"화가 났다","mis":"K1-2-u1-X06"}],"explanation":["떨려서 노랫말이 떠오르지 않았어요 — 마음이 꽁꽁.","신난 마음은 반짝반짝, 화난 마음은 우르릉 쾅쾅이에요.","『국어』 18쪽 내용 알기를 떠올려요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#2','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',1,'mc','auto','「내 마음을 보여 줄까?」 — 나만 뜀틀에 올라가서 「나」의 기분은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":2,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음을 보여 줄까?」 — 나만 뜀틀에 올라가서 「나」의 기분은?","options":[{"t":"신났다","correct":true},{"t":"떨렸다","mis":"K1-2-u1-X06"},{"t":"깜짝 놀랐다","mis":"K1-2-u1-X06"}],"explanation":["친구들이 부러워해서 마음이 반짝반짝 — 신났어요.","떨린 마음은 꽁꽁, 놀란 마음은 찌지직이에요.","『국어』 18쪽을 떠올려요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#3','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',1,'mc','auto','「내 마음을 보여 줄까?」 — 민호가 갑자기 달려들어 「나」의 기분은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":3,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음을 보여 줄까?」 — 민호가 갑자기 달려들어 「나」의 기분은?","options":[{"t":"깜짝 놀랐다","correct":true},{"t":"신났다","mis":"K1-2-u1-X06"},{"t":"떨렸다","mis":"K1-2-u1-X06"}],"explanation":["블록 성을 만드는데 민호가 달려들어 깜짝 놀랐어요 — 찌지직.","신난 마음은 반짝반짝이에요.","『국어』 18쪽을 떠올려요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#4','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',1,'mc','auto','「내 마음을 보여 줄까?」 — 성이 무너져서 민호에게 「나」의 기분은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":4,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음을 보여 줄까?」 — 성이 무너져서 민호에게 「나」의 기분은?","options":[{"t":"화가 났다","correct":true},{"t":"고마웠다","mis":"K1-2-u1-X06"},{"t":"신났다","mis":"K1-2-u1-X06"}],"explanation":["성이 와장창 무너져 화가 났어요 — 우르릉 쾅쾅.","고맙거나 신난 일이 아니에요.","『국어』 18쪽을 떠올려요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#5','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',2,'match','auto','『국어』 19쪽 낱말 알기 — 그림에 어울리는 흉내 내는 말을 작품에서 찾아 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C3","difficulty":2,"kind":"match","stem":"『국어』 19쪽 낱말 알기 — 그림에 어울리는 흉내 내는 말을 작품에서 찾아 이어 보세요.","pairs":[{"l":"💎 보석처럼 빛나는 마음","r":"반짝반짝"},{"l":"🧊 얼음처럼 언 마음","r":"꽁꽁"},{"l":"🌋 화산처럼 터지는 마음","r":"우르릉 쾅쾅"}],"mis":"K1-2-u1-X06","explanation":["보석은 반짝반짝, 얼음은 꽁꽁이에요.","화산은 우르릉 쾅쾅이에요.","작품의 그림을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
