INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#8','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',2,'mc','auto','「내 마음이 꽁꽁, 얼음처럼 꽁꽁!」에서 「꽁꽁」이 나타내는 마음은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":2,"kind":"mc","stem":"「내 마음이 꽁꽁, 얼음처럼 꽁꽁!」에서 「꽁꽁」이 나타내는 마음은?","options":[{"t":"떨려서 굳은 마음","correct":true},{"t":"신나서 들뜬 마음","mis":"K1-2-u1-X06"},{"t":"졸린 마음","mis":"K1-2-u1-X06"}],"explanation":["떨려서 노랫말이 떠오르지 않는 꽁꽁 언 마음이에요.","신난 마음은 반짝반짝이에요.","앞뒤 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#9','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',2,'ox','auto','마음도 흉내 내는 말로 나타낼 수 있어요.',ARRAY['K1-2-u1-X05']::text[],false,'{"seq":9,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"마음도 흉내 내는 말로 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"「내 마음이 반짝반짝」처럼 기분을 옮길 수 있으니까","correct":true},{"t":"흉내 내는 말은 동물 소리에만 쓰니까","mis":"K1-2-u1-X05"}],"mis":"K1-2-u1-X05","explanation":["「내 마음을 보여 줄까?」는 흉내 내는 말로 기분을 나타냈어요.","동물 소리에만 쓰는 게 아니에요.","네 장면의 흉내 내는 말을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_basic#10','kor',1,2,'u1','L05','g1_2_kor_u1_L05_basic','lesson_basic','K1-2-u1-C3',3,'mc','auto','「내 마음을 보여 줄까?」에서 「나」의 기분이 바뀐 차례로 알맞은 것은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":10,"concept":"K1-2-u1-C3","difficulty":3,"kind":"mc","stem":"「내 마음을 보여 줄까?」에서 「나」의 기분이 바뀐 차례로 알맞은 것은?","options":[{"t":"떨렸다 → 신났다 → 깜짝 놀랐다 → 화가 났다","correct":true},{"t":"신났다 → 떨렸다 → 화가 났다 → 깜짝 놀랐다","mis":"K1-2-u1-X06"},{"t":"화가 났다 → 깜짝 놀랐다 → 신났다 → 떨렸다","mis":"K1-2-u1-X06"}],"explanation":["노래 → 뜀틀 → 블록 성 → 성이 무너짐 차례예요.","꽁꽁 → 반짝반짝 → 찌지직 → 우르릉 쾅쾅으로 바뀌어요.","『국어』 18쪽 네 장면을 차례로 봐요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#1','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',2,'mc','auto','「내 마음이 찌지직, 번개처럼 찌지직!」은 어떤 일이 있을 때 든 마음인가요?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":1,"concept":"K1-2-u1-C3","difficulty":2,"kind":"mc","stem":"「내 마음이 찌지직, 번개처럼 찌지직!」은 어떤 일이 있을 때 든 마음인가요?","options":[{"t":"민호가 달려들어 깜짝 놀랐을 때","correct":true},{"t":"나만 뜀틀에 올랐을 때","mis":"K1-2-u1-X06"},{"t":"친구들 앞에서 노래할 때","mis":"K1-2-u1-X06"}],"explanation":["블록 성을 만드는데 민호가 달려들어 깜짝 놀랐어요.","뜀틀은 반짝반짝, 노래는 꽁꽁이에요.","세 번째 장면이에요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#2','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C2',2,'mc','auto','「별이 빛나고 있다.」보다 실감 나는 문장은?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":2,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"「별이 빛나고 있다.」보다 실감 나는 문장은?","options":[{"t":"별이 반짝반짝 빛나고 있다.","correct":true},{"t":"별이 많이 빛나고 있다.","mis":"K1-2-u1-X04"},{"t":"별이 빛나고 있다고 해요.","mis":"K1-2-u1-X04"}],"explanation":["반짝반짝을 넣으면 별이 빛나는 모습이 떠올라요.","흉내 내는 말이 없으면 모습이 그려지지 않아요.","『국어』 19쪽 문장 만들기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#3','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C2',3,'error','auto','「빗방울이 반짝반짝 떨어졌다.」 이 문장은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":3,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「빗방울이 반짝반짝 떨어졌다.」 이 문장은 무엇이 잘못되었나요?","options":[{"t":"반짝반짝은 빛나는 모양이라 빗방울이 떨어지는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"빗방울에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「떨어졌다」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["빗방울은 후드득 떨어져요.","반짝반짝은 별이나 보석이 빛나는 모양이에요.","장면을 먼저 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
