INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#5','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',3,'match','auto','『국어』 18쪽 — 있었던 일과 「나」의 기분을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C3","difficulty":3,"kind":"match","stem":"『국어』 18쪽 — 있었던 일과 「나」의 기분을 이어 보세요.","pairs":[{"l":"친구들 앞에서 노래를 부를 때","r":"떨렸다"},{"l":"나만 뜀틀에 올라가서","r":"신났다"},{"l":"민호가 갑자기 달려들어","r":"깜짝 놀랐다"},{"l":"성이 무너져서 민호에게","r":"화가 났다"}],"mis":"K1-2-u1-X06","explanation":["노래할 때는 떨렸고, 뜀틀에서는 신났어요.","민호가 달려들어 놀랐고, 성이 무너져 화가 났어요.","네 장면을 차례로 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
