INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#7','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',3,'ox','auto','「내 마음을 보여 줄까?」에서 흉내 내는 말은 「나」의 기분을 실감 나게 보여 줘요.',ARRAY['K1-2-u1-X05']::text[],false,'{"seq":7,"concept":"K1-2-u1-C3","difficulty":3,"kind":"ox","stem":"「내 마음을 보여 줄까?」에서 흉내 내는 말은 「나」의 기분을 실감 나게 보여 줘요.","answer":"O","reason_options":[{"t":"꽁꽁·반짝반짝·찌지직·우르릉 쾅쾅이 떨림·신남·놀람·화를 그려 주니까","correct":true},{"t":"흉내 내는 말은 기분과 상관없으니까","mis":"K1-2-u1-X05"}],"mis":"K1-2-u1-X05","explanation":["흉내 내는 말과 그림이 짝을 이루어 기분을 보여 줘요.","상관없는 게 아니라 기분을 더 생생하게 해 줘요.","네 장면의 그림을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#8','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',4,'sa','auto','「내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!」이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!」이 나타내는 마음을 한 낱말로 쓰세요.","answer":["화나요","화나","화났어요","화났어","화가나요","화가났어요","화","화남","화가난다","화난다","화가났다","화가나","속상해요","속상해","속상했어요"],"explanation":["성이 무너져 민호에게 화가 난 마음이에요.","신나거나 떨린 마음이 아니에요.","화산이 터지는 모습을 떠올려요."],"asset":{"type":"passage","lines":["친구들 앞에서 노래를 불렀어. 떨려서 노랫말이 떠오르지 않아. 내 마음이 꽁꽁, 얼음처럼 꽁꽁!","폴짝! 나만 뜀틀에 올랐어. 친구들 모두 날 부러워해. 내 마음이 반짝반짝, 보석처럼 반짝반짝!","블록으로 멋진 성을 만드는데, 민호가 달려들어 깜짝 놀랐어. 내 마음이 찌지직, 번개처럼 찌지직!","내가 만든 성이 와장창 무너졌어. 민호한테 너무 화가 나. 내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!"],"title":"내 마음을 보여 줄까? (글·그림 윤진현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#9','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C2',4,'essay','teacher','『국어』 19쪽 — 「두근두근」을 넣어 문장을 만들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"『국어』 19쪽 — 「두근두근」을 넣어 문장을 만들어 쓰세요.","answer_guide":{"answer":"예: 가슴이 두근두근 떨렸다. / 발표를 앞두고 두근두근했다. — 두근두근과 어울리면 맞아요.","scoring_points":["두근두근이 들어갔는가","가슴이 뛰는 상황과 어울리는가","문장이 자연스러운가"]},"explanation":["두근두근은 가슴이 뛰는 모양이에요.","설레거나 떨릴 때 써요.","가슴에 손을 대 보고 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L05_challenge#10','kor',1,2,'u1','L05','g1_2_kor_u1_L05_challenge','lesson_challenge','K1-2-u1-C3',4,'essay','teacher','『국어』 19쪽 자신과 관련짓기 — 여름 방학 때 있었던 일과 그때의 기분을 흉내 내는 말을 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C3","difficulty":4,"kind":"essay","stem":"『국어』 19쪽 자신과 관련짓기 — 여름 방학 때 있었던 일과 그때의 기분을 흉내 내는 말을 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 가족과 계곡에서 첨벙첨벙 물놀이했을 때 신났어. — 있었던 일 + 흉내 내는 말 + 기분이면 맞아요.","scoring_points":["있었던 일이 들어 있는가","흉내 내는 말이 들어갔는가","기분을 나타내는 말이 있는가"]},"explanation":["있었던 일, 흉내 내는 말, 기분을 함께 써요.","흉내 내는 말을 넣으면 더 실감 나요.","교과서 19쪽 친구들의 말을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#1','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 20쪽 1번 — 두 팔을 벌리고 환호하는 아이의 그림에 어울리는 말을 보기(기뻐요·슬퍼요·화나요·무서워요)에서 고르면?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 20쪽 1번 — 두 팔을 벌리고 환호하는 아이의 그림에 어울리는 말을 보기(기뻐요·슬퍼요·화나요·무서워요)에서 고르면?","options":[{"t":"기뻐요","correct":true},{"t":"슬퍼요","mis":"K1-2-u1-X07"},{"t":"무서워요","mis":"K1-2-u1-X07"}],"explanation":["환호하는 모습은 기쁜 기분이에요.","슬프거나 무서우면 그렇게 하지 않아요.","표정과 몸짓을 봐요."],"asset":{"type":"scene","icon":"🙌😄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#2','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 20쪽 1번 — 눈물을 흘리는 아이의 그림에 어울리는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":2,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 20쪽 1번 — 눈물을 흘리는 아이의 그림에 어울리는 말은?","options":[{"t":"슬퍼요","correct":true},{"t":"기뻐요","mis":"K1-2-u1-X07"},{"t":"화나요","mis":"K1-2-u1-X07"}],"explanation":["눈물을 흘리는 모습은 슬픈 기분이에요.","기쁘거나 화난 표정이 아니에요.","표정을 봐요."],"asset":{"type":"scene","icon":"😢"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#3','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 20쪽 1번 — 팔짱을 끼고 씩씩대는 아이의 그림에 어울리는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 20쪽 1번 — 팔짱을 끼고 씩씩대는 아이의 그림에 어울리는 말은?","options":[{"t":"화나요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X07"},{"t":"슬퍼요","mis":"K1-2-u1-X07"}],"explanation":["씩씩대는 모습은 화난 기분이에요.","무섭거나 슬픈 표정이 아니에요.","표정과 몸짓을 봐요."],"asset":{"type":"scene","icon":"😠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#4','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 20쪽 1번 — 떨며 움츠린 아이의 그림에 어울리는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 20쪽 1번 — 떨며 움츠린 아이의 그림에 어울리는 말은?","options":[{"t":"무서워요","correct":true},{"t":"기뻐요","mis":"K1-2-u1-X07"},{"t":"화나요","mis":"K1-2-u1-X07"}],"explanation":["떨며 움츠린 모습은 무서운 기분이에요.","기쁘거나 화난 모습이 아니에요.","몸짓을 봐요."],"asset":{"type":"scene","icon":"😨"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#5','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C4',2,'mc','auto','『국어』 21쪽 2번 — 기분을 나타내는 말을 더 찾았어요. 알맞지 않은 것은?',ARRAY['K1-2-u1-X08']::text[],false,'{"seq":5,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"『국어』 21쪽 2번 — 기분을 나타내는 말을 더 찾았어요. 알맞지 않은 것은?","options":[{"t":"필통","correct":true},{"t":"뿌듯해요","mis":"K1-2-u1-X08"},{"t":"후련해요","mis":"K1-2-u1-X08"}],"explanation":["필통은 물건 이름이라 기분이 아니에요.","뿌듯해요·후련해요는 마음을 나타내는 말이에요.","「마음이 ○○해요」로 바꿔 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#6','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','『국어』 22쪽 4번 — 민지가 지나가다 쳐서 주영이가 만든 성이 무너졌어요. 주영이가 가장 먼저 할 일은?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 22쪽 4번 — 민지가 지나가다 쳐서 주영이가 만든 성이 무너졌어요. 주영이가 가장 먼저 할 일은?","options":[{"t":"무슨 일이 있었는지 생각해 본다","correct":true},{"t":"큰 소리로 화를 낸다","mis":"K1-2-u1-X11"},{"t":"아무 말도 하지 않는다","mis":"K1-2-u1-X11"}],"explanation":["먼저 무슨 일이 있었는지 생각해요.","큰 소리나 침묵은 마음을 전하지 못해요.","네 단계의 첫 번째예요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"(지나가다가 주영이가 만든 성을 쳐서 무너뜨렸어요)"},{"who":"주영","text":"(생각) 민지에게 내 기분을 어떻게 말할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#7','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','『국어』 22쪽 4번 — 솔직하게 말했을 때 무엇을 생각해야 하나요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 22쪽 4번 — 솔직하게 말했을 때 무엇을 생각해야 하나요?","options":[{"t":"듣는 사람의 기분","correct":true},{"t":"민지를 혼내 줄 방법","mis":"K1-2-u1-X09"},{"t":"새 성을 쌓을 방법","mis":"K1-2-u1-X11"}],"explanation":["「내가 화를 내면 민지가 상처받을 거야」 — 듣는 사람의 기분을 생각해요.","혼내는 것은 배려하는 말하기가 아니에요.","네 단계의 세 번째예요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"(지나가다가 주영이가 만든 성을 쳐서 무너뜨렸어요)"},{"who":"주영","text":"(생각) 민지에게 내 기분을 어떻게 말할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#8','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','『국어』 22쪽 4번 — 「나」라는 말로 시작하며 정리한 생각을 말한 것은?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":8,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 22쪽 4번 — 「나」라는 말로 시작하며 정리한 생각을 말한 것은?","options":[{"t":"나는 내가 만든 성이 무너져서 정말 속상해.","correct":true},{"t":"너 때문에 성이 무너졌잖아!","mis":"K1-2-u1-X09"},{"t":"다시는 내 옆에 오지 마.","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","「너 때문에」와 「오지 마」는 상대를 탓하고 밀어내는 말이에요.","첫 낱말을 봐요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"(지나가다가 주영이가 만든 성을 쳐서 무너뜨렸어요)"},{"who":"주영","text":"(생각) 민지에게 내 기분을 어떻게 말할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#9','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',2,'blank','auto','『국어』 23쪽 5번 — 빈칸에 알맞은 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_basic#10','kor',1,2,'u1','L07','g1_2_kor_u1_L07_basic','lesson_basic','K1-2-u1-C5',3,'mc','auto','자신의 기분을 다른 사람에게 말할 때 알맞은 방법은?',ARRAY['K1-2-u1-X09','K1-2-u1-X12']::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"자신의 기분을 다른 사람에게 말할 때 알맞은 방법은?","options":[{"t":"「나」라는 말로 시작하고 있었던 일과 기분을 말한다","correct":true},{"t":"「너」로 시작해 상대의 잘못을 말한다","mis":"K1-2-u1-X09"},{"t":"기분은 말하지 않고 참는다","mis":"K1-2-u1-X12"}],"explanation":["「나」로 시작하고 있었던 일과 기분을 말해요.","「너」로 시작하면 탓하는 말이 되고, 참으면 마음이 전해지지 않아요.","『국어』 22쪽 아래 설명을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#1','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C4',2,'mc','auto','『국어』 21쪽 2번 — 어려운 숙제를 다 끝냈을 때 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"『국어』 21쪽 2번 — 어려운 숙제를 다 끝냈을 때 어울리는 기분을 나타내는 말은?","options":[{"t":"후련해요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X07"},{"t":"부끄러워요","mis":"K1-2-u1-X07"}],"explanation":["할 일을 다 끝내면 후련하고 뿌듯해요.","무섭거나 부끄러운 일이 아니에요.","그 자리의 나를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#2','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C4',2,'mc','auto','『국어』 21쪽 2번 — 여러 사람 앞에서 넘어졌을 때 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":2,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"『국어』 21쪽 2번 — 여러 사람 앞에서 넘어졌을 때 어울리는 기분을 나타내는 말은?","options":[{"t":"부끄러워요","correct":true},{"t":"편안해요","mis":"K1-2-u1-X07"},{"t":"후련해요","mis":"K1-2-u1-X07"}],"explanation":["여러 사람 앞에서 넘어지면 부끄러워요.","편안하거나 후련한 일이 아니에요.","그 자리의 나를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#3','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','「너 때문에 성이 무너졌잖아!」 이 말은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11','K1-2-u1-X10']::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「너 때문에 성이 무너졌잖아!」 이 말은 무엇이 잘못되었나요?","options":[{"t":"「너」로 시작해 상대를 탓했어요 — 「나는 성이 무너져서 속상해」로 말해요","correct":true,"mis_target":"K1-2-u1-X09"},{"t":"목소리가 작아서 잘못이에요","mis":"K1-2-u1-X11"},{"t":"「성」이라는 말을 빼야 해요","mis":"K1-2-u1-X10"}],"explanation":["「너 때문에」는 탓하는 말이라 듣는 사람이 상처받아요.","「나」로 시작해 있었던 일과 기분을 말해요.","『국어』 22쪽 4번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#4','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','『국어』 22쪽 4번 — 네 단계를 차례대로 바르게 놓은 것은?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":4,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"『국어』 22쪽 4번 — 네 단계를 차례대로 바르게 놓은 것은?","options":[{"t":"무슨 일이 있었는지 생각 → 솔직한 내 기분 생각 → 듣는 사람의 기분 생각 → 「나」로 시작해 말하기","correct":true},{"t":"「나」로 말하기 → 듣는 사람 기분 → 내 기분 → 무슨 일","mis":"K1-2-u1-X11"},{"t":"큰 소리 내기 → 내 기분 → 무슨 일 → 사과하기","mis":"K1-2-u1-X11"}],"explanation":["① 무슨 일 ② 내 기분 ③ 듣는 사람 기분 ④ 「나」로 말하기예요.","차례가 바뀌면 안 돼요.","손가락으로 네 걸음을 세어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#5','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'match','auto','『국어』 23쪽 5번 — 있었던 일과 내 기분을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":3,"kind":"match","stem":"『국어』 23쪽 5번 — 있었던 일과 내 기분을 이어 보세요.","pairs":[{"l":"나는 노래를 잘 부른다고 선생님께 칭찬받아서","r":"정말 뿌듯했어"},{"l":"나는 네가 색연필을 빌려줘서","r":"고마웠어"},{"l":"나는 기준이가 생일 선물을 줘서","r":"행복했어"}],"mis":"K1-2-u1-X10","explanation":["칭찬받으면 뿌듯하고, 빌려주면 고마워요.","선물을 받으면 행복해요.","앞은 있었던 일, 뒤는 내 기분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
