INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#7','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',3,'ox','auto','「나」라는 말로 시작하기만 하면 뒤에 무슨 말을 해도 괜찮아요.',ARRAY['K1-2-u1-X10']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":3,"kind":"ox","stem":"「나」라는 말로 시작하기만 하면 뒤에 무슨 말을 해도 괜찮아요.","answer":"X","reason_options":[{"t":"「나는 네가 미워」처럼 탓하는 말이 들어가면 안 되니까","correct":true},{"t":"「나」로 시작하면 뭐든 괜찮으니까","mis":"K1-2-u1-X10"}],"mis":"K1-2-u1-X10","explanation":["「나」 뒤에는 있었던 일과 기분이 와야 해요.","탓하는 말이 들어가면 듣는 사람이 상처받아요.","「나는 (있었던 일)해서 (기분)했어」 틀을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#8','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C4',4,'sa','auto','『국어』 21쪽 2번 — 기분을 나타내는 말을 한 가지 쓰세요. (기뻐요·슬퍼요·화나요·무서워요 말고)','{}'::text[],false,'{"seq":8,"concept":"K1-2-u1-C4","difficulty":4,"kind":"sa","stem":"『국어』 21쪽 2번 — 기분을 나타내는 말을 한 가지 쓰세요. (기뻐요·슬퍼요·화나요·무서워요 말고)","answer":["신나요","뿌듯해요","행복해요","편안해요","후련해요","부끄러워요","고마워요","속상해요","걱정돼요","반가워요","즐거워요","궁금해요","심심해요","놀라워요","부러워요","답답해요","괜찮아요","설레요","떨려요","서운해요","미안해요","사랑해요","감사해요","졸려요","힘들어요","웃겨요","보고싶어요"],"explanation":["신나요·뿌듯해요·행복해요·편안해요·후련해요·부끄러워요 등이 있어요.","물건 이름이나 하는 일은 기분이 아니에요.","기분 나무를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#9','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','『국어』 23쪽 5번 — 친구와 있었던 일을 떠올려 「나는 (있었던 일)해서 (내 기분)했어.」로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"『국어』 23쪽 5번 — 친구와 있었던 일을 떠올려 「나는 (있었던 일)해서 (내 기분)했어.」로 쓰세요.","answer_guide":{"answer":"예: 나는 네가 색연필을 빌려줘서 고마웠어. / 나는 기준이가 생일 선물을 줘서 행복했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분을 나타내는 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","탓하는 말 대신 있었던 일을 말해요.","듣는 사람의 기분을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L07_challenge#10','kor',1,2,'u1','L07','g1_2_kor_u1_L07_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','「너 때문에 성이 무너졌잖아!」를 듣는 사람을 생각하며 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너 때문에 성이 무너졌잖아!」를 듣는 사람을 생각하며 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 내가 만든 성이 무너져서 정말 속상해. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["『국어』 22쪽 주영이의 말이 본보기예요.","「너 때문에」 대신 성이 무너진 일을 말해요.","첫 낱말을 「나」로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#1','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','「화내지 말고 예쁘게 말해요」 — 화를 내며 말하는 버릇이 있는 도치의 별명은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":1,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 화를 내며 말하는 버릇이 있는 도치의 별명은?","options":[{"t":"버럭쟁이","correct":true},{"t":"울보","mis":"K1-2-u1-X15"},{"t":"소곤쟁이","mis":"K1-2-u1-X15"}],"explanation":["화를 내며 말하는 버릇 때문에 별명이 버럭쟁이예요.","울보나 소곤쟁이가 아니에요.","『국어』 25쪽 내용 알기 (1)이에요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#2','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','「화내지 말고 예쁘게 말해요」 — 도치 머리 위에 생긴 것은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":2,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 도치 머리 위에 생긴 것은?","options":[{"t":"나쁜 말 구름","correct":true},{"t":"모자","mis":"K1-2-u1-X15"},{"t":"풍선","mis":"K1-2-u1-X15"}],"explanation":["도치 머리 위에 손바닥만 한 나쁜 말 구름이 생겼어요.","모자나 풍선이 아니에요.","이야기의 첫 부분을 떠올려요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#3','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','「화내지 말고 예쁘게 말해요」 — 나쁜 말 구름이 점점 커진 까닭은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 나쁜 말 구름이 점점 커진 까닭은?","options":[{"t":"도치가 자꾸 나쁜 말을 해서","correct":true},{"t":"비가 많이 와서","mis":"K1-2-u1-X15"},{"t":"친구들이 놀려서","mis":"K1-2-u1-X15"}],"explanation":["도치가 버럭버럭 화를 낼수록 구름이 커졌어요.","비나 친구들 때문이 아니에요.","『국어』 25쪽 내용 알기 (2)예요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#4','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',1,'mc','auto','「화내지 말고 예쁘게 말해요」 — 도치는 나쁜 말 구름을 어떻게 없앴나요?',ARRAY['K1-2-u1-X09','K1-2-u1-X15']::text[],false,'{"seq":4,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 도치는 나쁜 말 구름을 어떻게 없앴나요?","options":[{"t":"바르고 고운 말로 예쁘게 말해서","correct":true},{"t":"더 크게 화를 내서","mis":"K1-2-u1-X09"},{"t":"구름을 손으로 밀어서","mis":"K1-2-u1-X15"}],"explanation":["「얘들아, 난 너희들이랑 함께 놀면 좋겠어.」라고 예쁘게 말하자 구름이 사라졌어요.","화를 내면 구름이 더 커져요.","『국어』 25쪽 내용 알기 (3)이에요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#5','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'match','auto','『국어』 25쪽 낱말 알기 — 낱말과 뜻을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":2,"kind":"match","stem":"『국어』 25쪽 낱말 알기 — 낱말과 뜻을 이어 보세요.","pairs":[{"l":"버럭버럭","r":"화가 나서 소리를 지르는 모양"},{"l":"소곤소곤","r":"작은 목소리로 가만가만 이야기하는 소리 또는 모양"},{"l":"감쪽같이","r":"꾸미거나 고친 것이 전혀 알아챌 수 없을 정도로 티가 나지 않게"}],"mis":"K1-2-u1-X15","explanation":["버럭버럭은 화내는 모양, 소곤소곤은 작게 말하는 모양이에요.","감쪽같이는 티가 나지 않게예요.","이야기에서 쓰인 장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#6','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','「할머니는 도치에게 소곤소곤 이야기해 주었어요.」에서 「소곤소곤」의 뜻은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"「할머니는 도치에게 소곤소곤 이야기해 주었어요.」에서 「소곤소곤」의 뜻은?","options":[{"t":"작은 목소리로 가만가만 말하는 모양","correct":true},{"t":"화가 나서 소리 지르는 모양","mis":"K1-2-u1-X15"},{"t":"티가 나지 않게","mis":"K1-2-u1-X15"}],"explanation":["소곤소곤은 작은 목소리로 가만가만 이야기하는 모양이에요.","화내는 모양은 버럭버럭이에요.","『국어』 25쪽 낱말 알기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#7','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','『국어』 26쪽 ①장면 — 도치가 「내가 먼저 탈 거야!」 하고 화를 냈어요. 듣는 사람을 생각하며 바꾸어 말한 것은?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 26쪽 ①장면 — 도치가 「내가 먼저 탈 거야!」 하고 화를 냈어요. 듣는 사람을 생각하며 바꾸어 말한 것은?","options":[{"t":"나는 그네를 타고 싶었는데 기다려서 속상했어. 다음엔 같이 타자.","correct":true},{"t":"너는 왜 맨날 먼저 타!","mis":"K1-2-u1-X09"},{"t":"비켜, 내 차례야.","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","「너는 왜」와 「비켜」는 탓하고 밀어내는 말이에요.","첫 낱말을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#8','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'blank','auto','『국어』 27쪽 — 할머니께서 맛있는 음식을 만들어 주셨을 때. 빈칸에 알맞은 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#9','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',2,'blank','auto','『국어』 27쪽 — 친구가 큰 목소리로 소리쳤을 때. 빈칸에 알맞은 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_basic#10','kor',1,2,'u1','L09','g1_2_kor_u1_L09_basic','lesson_basic','K1-2-u1-C5',3,'mc','auto','『국어』 27쪽 — 동생이 우유를 쏟아서 내 책이 젖었을 때 듣는 사람을 생각하며 말한 것은?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"『국어』 27쪽 — 동생이 우유를 쏟아서 내 책이 젖었을 때 듣는 사람을 생각하며 말한 것은?","options":[{"t":"나는 내 책이 우유에 젖어서 많이 속상했어.","correct":true},{"t":"너 때문에 책 다 망쳤잖아!","mis":"K1-2-u1-X09"},{"t":"저리 가!","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","「너 때문에」와 「저리 가」는 상대를 탓하고 밀어내는 말이에요.","동생이 상처받지 않게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#1','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',2,'mc','auto','「화내지 말고 예쁘게 말해요」 — 도치가 친구 치치에게 화를 낸 까닭은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":1,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 도치가 친구 치치에게 화를 낸 까닭은?","options":[{"t":"치치가 먼저 왔는데도 자기가 먼저 타려고 해서","correct":true},{"t":"치치가 도치를 때려서","mis":"K1-2-u1-X15"},{"t":"치치가 구름을 만들어서","mis":"K1-2-u1-X15"}],"explanation":["「내가 먼저 탈 거야!」 치치가 먼저 왔는데도 화를 냈어요.","치치가 잘못한 것이 아니에요.","이야기 가운데 부분이에요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#2','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',2,'mc','auto','「화내지 말고 예쁘게 말해요」 — 도치가 슬퍼서 펑펑 운 까닭은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":2,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 도치가 슬퍼서 펑펑 운 까닭은?","options":[{"t":"구름 때문에 친구들이랑 놀 수가 없어서","correct":true},{"t":"할머니가 혼내서","mis":"K1-2-u1-X15"},{"t":"그네가 망가져서","mis":"K1-2-u1-X15"}],"explanation":["「구름 때문에 친구들이랑 놀 수가 없잖아.」 하고 울었어요.","할머니는 도와주셨어요.","이야기 가운데 부분이에요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#3','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','「너는 왜 맨날 먼저 타!」 이 말은 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11','K1-2-u1-X10']::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「너는 왜 맨날 먼저 타!」 이 말은 무엇이 잘못되었나요?","options":[{"t":"「너」로 시작해 상대를 탓했어요 — 「나는 기다려서 속상했어」로 말해요","correct":true,"mis_target":"K1-2-u1-X09"},{"t":"목소리가 작아서 잘못이에요","mis":"K1-2-u1-X11"},{"t":"「타」라는 말을 빼야 해요","mis":"K1-2-u1-X10"}],"explanation":["「너는 왜」는 탓하는 말이에요.","「나」로 시작해 있었던 일과 기분을 말해요.","도치의 「내가 먼저 탈 거야!」와 같은 말하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#4','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','「나는 네가 정말 미워.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":4,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 네가 정말 미워.」 이 말은 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 내 기분 대신 상대를 탓하는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 「너는」으로 바꿔야 해요","mis":"K1-2-u1-X09"},{"t":"더 짧게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「네가 미워」는 탓하는 말이에요.","「나는 책이 젖어서 속상했어」처럼 일과 기분을 넣어요.","두 칸이 다 있는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#5','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'match','auto','『국어』 27쪽 — 상황과 「나」로 시작한 말을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":3,"kind":"match","stem":"『국어』 27쪽 — 상황과 「나」로 시작한 말을 이어 보세요.","pairs":[{"l":"할머니께서 맛있는 음식을 만들어 주셨을 때","r":"나는 맛있는 음식을 먹게 되어서 기뻤어."},{"l":"친구가 큰 목소리로 소리쳤을 때","r":"나는 친구가 큰 목소리로 말해서 깜짝 놀랐어."},{"l":"동생이 우유를 쏟아서 내 책이 젖었을 때","r":"나는 내 책이 우유에 젖어서 많이 속상했어."}],"mis":"K1-2-u1-X10","explanation":["음식은 기쁘고, 큰 소리는 놀라요.","책이 젖으면 속상해요.","상황마다 내 기분을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#6','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'mc','auto','도치가 「얘들아, 난 너희들이랑 함께 놀면 좋겠어.」라고 말한 뒤 일어난 일은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"도치가 「얘들아, 난 너희들이랑 함께 놀면 좋겠어.」라고 말한 뒤 일어난 일은?","options":[{"t":"친구들과 사이좋게 놀 수 있었고 구름이 감쪽같이 사라졌어요","correct":true},{"t":"구름이 더 커졌어요","mis":"K1-2-u1-X15"},{"t":"친구들이 도망갔어요","mis":"K1-2-u1-X15"}],"explanation":["예쁘게 말하자 친구들이 놀라 쳐다보았고, 함께 놀 수 있어서 기뻤어요.","구름은 감쪽같이 사라졌어요.","이야기의 끝부분이에요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#7','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',3,'ox','auto','자신의 언어 습관을 돌아보면 듣는 사람을 생각하며 말하는 데 도움이 돼요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":3,"kind":"ox","stem":"자신의 언어 습관을 돌아보면 듣는 사람을 생각하며 말하는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"도치처럼 화내며 말하는 버릇을 알아야 고칠 수 있으니까","correct":true},{"t":"말 습관은 돌아볼 필요가 없으니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["자신의 말 습관을 점검하면 「나 전달법」이 효과적임을 알 수 있어요.","돌아보지 않으면 나쁜 말 구름이 커져요.","『국어』 일반화하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#8','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',4,'sa','auto','「화내지 말고 예쁘게 말해요」에서 도치에게 나쁜 말 구름을 없애는 방법을 알려 준 사람은 누구인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u1-C5","difficulty":4,"kind":"sa","stem":"「화내지 말고 예쁘게 말해요」에서 도치에게 나쁜 말 구름을 없애는 방법을 알려 준 사람은 누구인가요?","answer":["양산할머니","양산을쓴할머니","할머니","작은양산을쓴할머니","양산 할머니","양산을 쓴 할머니"],"explanation":["어디선가 작은 양산을 쓴 할머니가 나타나 소곤소곤 알려 주었어요.","치치나 친구들이 아니에요.","이야기 가운데 부분이에요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#9','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','『국어』 26쪽 — ②장면 「구름 때문에 친구들이랑 놀 수가 없잖아.」를 듣는 사람을 생각하며 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"『국어』 26쪽 — ②장면 「구름 때문에 친구들이랑 놀 수가 없잖아.」를 듣는 사람을 생각하며 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 친구들이랑 놀지 못해서 슬펐어. 같이 놀고 싶어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","탓하는 말 대신 내 기분을 말해요.","도치의 마지막 말이 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L09_challenge#10','kor',1,2,'u1','L09','g1_2_kor_u1_L09_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','『국어』 27쪽 — 친구가 큰 목소리로 소리쳤을 때, 듣는 사람을 생각하며 자신의 기분이 잘 드러나게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"『국어』 27쪽 — 친구가 큰 목소리로 소리쳤을 때, 듣는 사람을 생각하며 자신의 기분이 잘 드러나게 쓰세요.","answer_guide":{"answer":"예: 나는 친구가 큰 목소리로 말해서 깜짝 놀랐어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 (있었던 일)해서 (기분)했어」로 써요.","「너 왜 소리쳐!」는 탓하는 말이에요.","첫 낱말을 「나」로 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#1','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 28쪽 — 친구들과 놀이를 할 때 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 28쪽 — 친구들과 놀이를 할 때 어울리는 기분을 나타내는 말은?","options":[{"t":"신나요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X07"},{"t":"미안해요","mis":"K1-2-u1-X07"}],"explanation":["친구들과 놀 때는 신나고 즐거워요.","무섭거나 미안한 일이 아니에요.","그 자리의 나를 떠올려요."],"asset":{"type":"scene","icon":"⚽🧒🧒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#2','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 28쪽 — 가족과 함께 나들이할 때 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":2,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 28쪽 — 가족과 함께 나들이할 때 어울리는 기분을 나타내는 말은?","options":[{"t":"즐거워요","correct":true},{"t":"속상해요","mis":"K1-2-u1-X07"},{"t":"부끄러워요","mis":"K1-2-u1-X07"}],"explanation":["가족과 나들이하면 즐겁고 행복해요.","속상하거나 부끄러운 일이 아니에요.","그 자리의 나를 떠올려요."],"asset":{"type":"scene","icon":"👨‍👩‍👧🧺"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#3','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 28쪽 — 실수로 친구에게 피해를 줬을 때 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 28쪽 — 실수로 친구에게 피해를 줬을 때 어울리는 기분을 나타내는 말은?","options":[{"t":"미안해요","correct":true},{"t":"신나요","mis":"K1-2-u1-X07"},{"t":"뿌듯해요","mis":"K1-2-u1-X07"}],"explanation":["실수로 피해를 주면 미안한 마음이 들어요.","신나거나 뿌듯한 일이 아니에요.","친구의 마음을 생각해요."],"asset":{"type":"scene","icon":"🎨💧😳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#4','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C4',1,'mc','auto','『국어』 28쪽 — 친구가 어려움을 당했을 때 어울리는 기분을 나타내는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 28쪽 — 친구가 어려움을 당했을 때 어울리는 기분을 나타내는 말은?","options":[{"t":"걱정돼요","correct":true},{"t":"즐거워요","mis":"K1-2-u1-X07"},{"t":"심심해요","mis":"K1-2-u1-X07"}],"explanation":["친구가 힘들면 걱정되고 도와주고 싶어요.","즐겁거나 심심한 일이 아니에요.","친구의 마음을 생각해요."],"asset":{"type":"scene","icon":"🤕🤝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#5','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','『국어』 28쪽 역할놀이 차례 — ① 상황 알아보기 다음에 할 일은?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 28쪽 역할놀이 차례 — ① 상황 알아보기 다음에 할 일은?","options":[{"t":"상황 속 역할 정하기","correct":true},{"t":"상황을 바꾸어 계속하기","mis":"K1-2-u1-X11"},{"t":"점수 매기기","mis":"K1-2-u1-X11"}],"explanation":["① 상황 알아보기 ② 역할 정하기 ③ 기분 말 정하기 ④ 역할놀이 ⑤ 상황 바꾸기예요.","상황 바꾸기는 마지막이에요.","교과서 28쪽 차례를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#6','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','지도서 「줄을 서시오」 상황 카드 — 친구가 「친구야, 우리 나가서 축구하자.」 했지만 숙제가 남았어요. 상황에 알맞은 말은?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"지도서 「줄을 서시오」 상황 카드 — 친구가 「친구야, 우리 나가서 축구하자.」 했지만 숙제가 남았어요. 상황에 알맞은 말은?","options":[{"t":"숙제 마칠 때까지 조금만 기다려 줄 수 있니?","correct":true},{"t":"싫어, 안 해.","mis":"K1-2-u1-X09"},{"t":"(대답하지 않는다)","mis":"K1-2-u1-X11"}],"explanation":["배려하며 상황에 알맞게 말했어요.","「싫어」나 침묵은 듣는 사람을 생각하지 않은 말이에요.","친구 마음을 생각하며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#7','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'mc','auto','상황 카드 — 친구가 「앗! 미안해.」 하고 사과했어요. 알맞은 대답은?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"상황 카드 — 친구가 「앗! 미안해.」 하고 사과했어요. 알맞은 대답은?","options":[{"t":"괜찮아. 나는 조금 놀랐지만 이제 괜찮아.","correct":true},{"t":"너 진짜 조심 좀 해!","mis":"K1-2-u1-X09"},{"t":"(화를 내며 가 버린다)","mis":"K1-2-u1-X11"}],"explanation":["사과를 받아 주며 내 기분을 말했어요.","탓하거나 가 버리면 마음이 전해지지 않아요.","듣는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#8','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C4',2,'match','auto','『국어』 28쪽 상황과 어울리는 기분을 나타내는 말을 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"『국어』 28쪽 상황과 어울리는 기분을 나타내는 말을 이어 보세요.","pairs":[{"l":"친구들과 놀이를 할 때","r":"신나요"},{"l":"실수로 친구에게 피해를 줬을 때","r":"미안해요"},{"l":"친구가 어려움을 당했을 때","r":"걱정돼요"}],"mis":"K1-2-u1-X07","explanation":["놀 때는 신나고, 실수하면 미안해요.","친구가 힘들면 걱정돼요.","상황마다 내 마음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#9','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',2,'blank','auto','빈칸에 알맞은 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_basic#10','kor',1,2,'u1','L11','g1_2_kor_u1_L11_basic','lesson_basic','K1-2-u1-C5',3,'mc','auto','역할놀이를 할 때 지킬 점으로 알맞은 것은?',ARRAY['K1-2-u1-X11','K1-2-u1-X09']::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"역할놀이를 할 때 지킬 점으로 알맞은 것은?","options":[{"t":"상대를 놀리거나 나쁜 말을 쓰지 않고, 역할을 바꾸어 가며 해요","correct":true},{"t":"한 사람이 계속 같은 역할만 해요","mis":"K1-2-u1-X11"},{"t":"실감 나게 하려고 큰 소리로 화를 내요","mis":"K1-2-u1-X09"}],"explanation":["나쁜 말을 쓰지 않고 역할을 바꾸어 가며 해요.","특정 역할에 고정되지 않도록 해요.","지도서 활동의 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#1','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C4',2,'mc','auto','친구가 넘어져 무릎을 다쳤어요. 어떻게 말할까요?',ARRAY['K1-2-u1-X09','K1-2-u1-X12']::text[],false,'{"seq":1,"concept":"K1-2-u1-C4","difficulty":2,"kind":"mc","stem":"친구가 넘어져 무릎을 다쳤어요. 어떻게 말할까요?","options":[{"t":"많이 아프니? 나는 네가 다쳐서 걱정돼.","correct":true},{"t":"조심 좀 하지.","mis":"K1-2-u1-X09"},{"t":"내가 먼저 갈게.","mis":"K1-2-u1-X12"}],"explanation":["친구가 어려울 때는 걱정하는 마음을 말해 줘요.","「조심 좀 하지」는 탓하는 말이에요.","친구 마음을 생각해요."],"asset":{"type":"scene","icon":"🤕🤝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#2','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',2,'mc','auto','상황 카드 — 비 오는 날 우산을 털다가 친구 옷이 젖었어요. 친구가 「미안해! 옷 많이 젖었니?」 하면?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":2,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"상황 카드 — 비 오는 날 우산을 털다가 친구 옷이 젖었어요. 친구가 「미안해! 옷 많이 젖었니?」 하면?","options":[{"t":"괜찮아. 나는 조금 놀랐지만 금방 마를 거야.","correct":true},{"t":"너 때문에 다 젖었잖아!","mis":"K1-2-u1-X09"},{"t":"(화를 내며 가 버린다)","mis":"K1-2-u1-X11"}],"explanation":["사과를 받아 주며 내 기분을 말했어요.","「너 때문에」는 탓하는 말이에요.","듣는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#3','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','역할놀이에서 「너 때문에 우리 편이 졌잖아!」라고 말했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":3,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"역할놀이에서 「너 때문에 우리 편이 졌잖아!」라고 말했어요. 무엇이 잘못되었나요?","options":[{"t":"「너」로 시작해 친구를 탓했어요 — 「나는 져서 아쉬웠어」로 말해요","correct":true,"mis_target":"K1-2-u1-X09"},{"t":"목소리가 작아서 잘못이에요","mis":"K1-2-u1-X11"},{"t":"놀이에서는 아무 말이나 해도 돼요","mis":"K1-2-u1-X09"}],"explanation":["역할놀이에서도 부적절한 말은 쓰지 않아요.","「나」로 시작해 내 기분을 말해요.","첫 낱말을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#4','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'error','auto','역할놀이 차례를 적었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#5','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'match','auto','지도서 상황 카드와 알맞은 말을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u1-C5","difficulty":3,"kind":"match","stem":"지도서 상황 카드와 알맞은 말을 이어 보세요.","pairs":[{"l":"「친구야, 우리 나가서 축구하자.」(숙제가 남았을 때)","r":"숙제 마칠 때까지 조금만 기다려 줄 수 있니?"},{"l":"「앗! 미안해.」(물감이 튀었을 때)","r":"괜찮아. 다음엔 조심해 줘."},{"l":"「미안해! 옷 많이 젖었니?」(우산 물이 튀었을 때)","r":"조금 젖었지만 괜찮아. 금방 마를 거야."}],"mis":"K1-2-u1-X09","explanation":["상황에 알맞게 배려하며 말해요.","사과는 받아 주고 내 기분을 말해요.","「줄을 서시오」 놀이의 상황 카드예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#6','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C4',3,'mc','auto','같은 「친구들과 놀이를 할 때」인데 한 친구는 「신나요」, 다른 친구는 「속상해요」라고 했어요. 왜 그럴까요?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":6,"concept":"K1-2-u1-C4","difficulty":3,"kind":"mc","stem":"같은 「친구들과 놀이를 할 때」인데 한 친구는 「신나요」, 다른 친구는 「속상해요」라고 했어요. 왜 그럴까요?","options":[{"t":"유사한 상황이라도 참여자마다 느끼는 기분이 다를 수 있어서","correct":true},{"t":"한 친구가 틀려서","mis":"K1-2-u1-X07"},{"t":"놀이가 재미없어서","mis":"K1-2-u1-X07"}],"explanation":["같은 상황이라도 사람마다 기분이 다를 수 있어요.","기분에는 맞고 틀린 것이 없어요.","서로 기분을 말해 주면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#7','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',3,'ox','auto','역할놀이에서 역할을 바꾸어 보면 다른 사람의 마음도 느낄 수 있어요.',ARRAY['K1-2-u1-X12']::text[],false,'{"seq":7,"concept":"K1-2-u1-C5","difficulty":3,"kind":"ox","stem":"역할놀이에서 역할을 바꾸어 보면 다른 사람의 마음도 느낄 수 있어요.","answer":"O","reason_options":[{"t":"친구 역할을 맡으면 그 사람 처지에서 기분을 생각하게 되니까","correct":true},{"t":"역할놀이는 재미로만 하니까","mis":"K1-2-u1-X12"}],"mis":"K1-2-u1-X12","explanation":["역할을 바꾸면 다른 사람의 처지에서 기분을 느껴요.","그래서 배려하는 말하기를 배울 수 있어요.","지도서 참고 자료 「역할극의 성격」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#8','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C4',4,'sa','auto','실수로 친구에게 피해를 줬을 때 드는 기분을 나타내는 말을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u1-C4","difficulty":4,"kind":"sa","stem":"실수로 친구에게 피해를 줬을 때 드는 기분을 나타내는 말을 한 낱말로 쓰세요.","answer":["미안해요","미안해","미안하다","미안했어요","미안했어","미안","미안함","죄송해요","죄송합니다","죄송","부끄러워요","부끄러워"],"explanation":["실수로 피해를 주면 미안한 마음이 들어요.","신나거나 뿌듯한 일이 아니에요.","친구 마음을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#9','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','『국어』 28쪽 — 「가족과 함께 나들이할 때」 역할놀이에서 할 말을 기분을 나타내는 말을 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"『국어』 28쪽 — 「가족과 함께 나들이할 때」 역할놀이에서 할 말을 기분을 나타내는 말을 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 나는 가족과 나들이를 와서 정말 즐거워! / 나는 아빠가 김밥을 싸 주셔서 행복했어. — 기분을 나타내는 말이 들어 있으면 맞아요.","scoring_points":["기분을 나타내는 말이 들어갔는가","상황과 어울리는가","문장이 자연스러운가"]},"explanation":["즐거워요·행복해요처럼 나들이와 어울리는 기분 말을 넣어요.","「나」로 시작하면 더 좋아요.","나들이 장면을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_L11_challenge#10','kor',1,2,'u1','L11','g1_2_kor_u1_L11_challenge','lesson_challenge','K1-2-u1-C5',4,'essay','teacher','지도서 「줄을 서시오」 — 친구가 「친구야, 우리 나가서 축구하자.」라고 했어요. 상황에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"지도서 「줄을 서시오」 — 친구가 「친구야, 우리 나가서 축구하자.」라고 했어요. 상황에 알맞은 말을 쓰세요.","answer_guide":{"answer":"예: 좋아, 나도 축구하고 싶었어! / 숙제 마칠 때까지 조금만 기다려 줄 수 있니? — 상황에 알맞고 배려하는 말이면 맞아요.","scoring_points":["상황에 알맞은 대답인가","듣는 사람을 생각한 말인가","문장이 자연스러운가"]},"explanation":["함께하고 싶으면 기쁘게, 어려우면 까닭을 말하며 배려해요.","「싫어」만 하면 듣는 사람이 서운해요.","상황 카드 ③의 말이 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#1','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C1',1,'mc','auto','『국어』 10쪽 글에서 구름이 떠 있는 모양을 흉내 낸 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 10쪽 글에서 구름이 떠 있는 모양을 흉내 낸 말은?","options":[{"t":"둥실둥실","correct":true},{"t":"구름이","mis":"K1-2-u1-X01"},{"t":"가을","mis":"K1-2-u1-X01"}],"explanation":["구름이 둥실둥실 떠 있어요.","구름·가을은 이름이에요.","모양을 옮긴 말을 찾아요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#2','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C1',1,'mc','auto','「둥실둥실」, 「야옹」처럼 모양이나 소리를 나타내는 말을 무엇이라고 하나요?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"「둥실둥실」, 「야옹」처럼 모양이나 소리를 나타내는 말을 무엇이라고 하나요?","options":[{"t":"흉내 내는 말","correct":true},{"t":"기분을 나타내는 말","mis":"K1-2-u1-X01"},{"t":"이름","mis":"K1-2-u1-X01"}],"explanation":["모양이나 소리를 나타내는 말이 흉내 내는 말이에요.","기분을 나타내는 말은 기뻐요 같은 말이에요.","『국어』 10쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#3','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',1,'mc','auto','『국어』 20쪽 — 두 팔 벌려 환호하는 아이의 기분은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 20쪽 — 두 팔 벌려 환호하는 아이의 기분은?","options":[{"t":"기뻐요","correct":true},{"t":"슬퍼요","mis":"K1-2-u1-X07"},{"t":"무서워요","mis":"K1-2-u1-X07"}],"explanation":["환호하는 모습은 기뻐요.","슬프거나 무서운 표정이 아니에요.","표정을 봐요."],"asset":{"type":"scene","icon":"🙌😄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#4','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',1,'mc','auto','『국어』 9쪽 — 놀이공원 장면에 어울리는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 9쪽 — 놀이공원 장면에 어울리는 말은?","options":[{"t":"신나요","correct":true},{"t":"속상해요","mis":"K1-2-u1-X07"},{"t":"걱정돼요","mis":"K1-2-u1-X07"}],"explanation":["놀이공원은 신나고 즐거워요.","속상하거나 걱정되는 일이 아니에요.","기분 나무를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#5','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',1,'blank','auto','『국어』 30쪽 1번 — 빈칸에 알맞은 흉내 내는 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#6','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은?","options":[{"t":"나는 내가 만든 성이 무너져서 정말 속상해.","correct":true},{"t":"너 때문에 성이 무너졌잖아!","mis":"K1-2-u1-X09"},{"t":"다시는 내 옆에 오지 마.","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","탓하거나 밀어내는 말이 아니에요.","『국어』 22쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#7','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C6',1,'mc','auto','『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?","options":[{"t":"곰이 그림책을 봅니다.","correct":true},{"t":"그림책이 곰을 봅니다.","mis":"K1-2-u1-X13"},{"t":"곰이 그림책을 마십니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(곰이) 무엇을(그림책을) 어찌하다(봅니다)예요.","그림책이 곰을 볼 수 없고, 그림책을 마실 수도 없어요.","낱말을 따라가며 문장을 만들어요."],"asset":{"type":"scene","icon":"🐻📖"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#8','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C3',1,'mc','auto','「내 마음이 꽁꽁, 얼음처럼 꽁꽁!」이 나타내는 마음은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음이 꽁꽁, 얼음처럼 꽁꽁!」이 나타내는 마음은?","options":[{"t":"떨려요","correct":true},{"t":"신나요","mis":"K1-2-u1-X06"},{"t":"화나요","mis":"K1-2-u1-X06"}],"explanation":["떨려서 노랫말이 떠오르지 않는 마음이에요.","신난 마음은 반짝반짝이에요.","첫 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#9','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C1',2,'match','auto','『국어』 11쪽 — 그림과 어울리는 흉내 내는 말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"『국어』 11쪽 — 그림과 어울리는 흉내 내는 말을 이어 보세요.","pairs":[{"l":"🕰️ 시계","r":"째깍째깍"},{"l":"🐰 토끼","r":"깡충깡충"},{"l":"☁️ 구름","r":"둥실둥실"}],"mis":"K1-2-u1-X03","explanation":["시계는 째깍째깍, 토끼는 깡충깡충이에요.","구름은 둥실둥실이에요.","소리인지 모양인지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#10','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',2,'mc','auto','『국어』 13쪽 — 더 실감 나는 문장은?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"『국어』 13쪽 — 더 실감 나는 문장은?","options":[{"t":"고양이가 「야옹」 하고 울었다.","correct":true},{"t":"고양이가 울었다.","mis":"K1-2-u1-X04"},{"t":"고양이가 많이 울었다.","mis":"K1-2-u1-X04"}],"explanation":["야옹을 넣으면 소리가 들리는 것 같아요.","흉내 내는 말이 없으면 소리가 떠오르지 않아요.","교과서 13쪽 친구의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
