INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#12','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',2,'match','auto','『국어』 27쪽 — 상황과 그때의 기분을 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"『국어』 27쪽 — 상황과 그때의 기분을 이어 보세요.","pairs":[{"l":"할머니께서 맛있는 음식을 만들어 주셨을 때","r":"기뻤어"},{"l":"친구가 큰 목소리로 소리쳤을 때","r":"깜짝 놀랐어"},{"l":"동생이 우유를 쏟아서 내 책이 젖었을 때","r":"속상했어"}],"mis":"K1-2-u1-X07","explanation":["음식은 기쁘고, 큰 소리는 놀라요.","책이 젖으면 속상해요.","나라면 어떤 마음일지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
