INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#14','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',2,'mc','auto','『국어』 22쪽 — 기분을 말하기 전에 가장 먼저 할 일은?',ARRAY['K1-2-u1-X11']::text[],false,'{"seq":14,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 22쪽 — 기분을 말하기 전에 가장 먼저 할 일은?","options":[{"t":"무슨 일이 있었는지 생각해 본다","correct":true},{"t":"큰 소리부터 낸다","mis":"K1-2-u1-X11"},{"t":"아무 말도 하지 않는다","mis":"K1-2-u1-X11"}],"explanation":["무슨 일이 있었는지부터 생각해요.","큰 소리나 침묵은 마음을 전하지 못해요.","네 단계의 첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
