INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#18','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',3,'error','auto','「병아리가 울긋불긋 소리를 냅니다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「병아리가 울긋불긋 소리를 냅니다.」 무엇이 잘못되었나요?","options":[{"t":"울긋불긋은 단풍 색깔 모양이라 병아리 소리와 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"병아리에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「소리를 냅니다」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["병아리는 삐악삐악이에요.","울긋불긋은 단풍이에요.","12쪽 보기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#19','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C4',3,'ox','auto','『국어』 31쪽 — 「너 때문이라고 말한다」는 자신의 기분을 말하는 알맞은 방법이에요.',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"『국어』 31쪽 — 「너 때문이라고 말한다」는 자신의 기분을 말하는 알맞은 방법이에요.","answer":"X","reason_options":[{"t":"상대를 탓하는 말이라 듣는 사람이 상처받으니까","correct":true},{"t":"기분은 솔직하게 말해야 하니까","mis":"K1-2-u1-X09"}],"mis":"K1-2-u1-X09","explanation":["「너 때문」은 탓하는 말이에요.","「나」로 시작해 있었던 일과 기분을 말해요.","31쪽 관람차에서 색칠하지 않는 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#20','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',3,'mc','auto','「화내지 말고 예쁘게 말해요」 — 나쁜 말 구름이 커진 까닭은?',ARRAY['K1-2-u1-X15']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 나쁜 말 구름이 커진 까닭은?","options":[{"t":"도치가 자꾸 나쁜 말을 해서","correct":true},{"t":"비가 와서","mis":"K1-2-u1-X15"},{"t":"친구들이 놀려서","mis":"K1-2-u1-X15"}],"explanation":["버럭버럭 화를 낼수록 구름이 커졌어요.","비나 친구 때문이 아니에요.","25쪽 내용 알기 (2)예요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#21','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',3,'error','auto','「나는 네가 정말 미워.」 「나」로 시작했는데 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 네가 정말 미워.」 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 내 기분 대신 상대를 탓하는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 「너는」으로 바꿔야 해요","mis":"K1-2-u1-X09"},{"t":"더 짧게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「네가 미워」는 탓하는 말이에요.","「나는 책이 젖어서 속상했어」처럼 일과 기분을 넣어요.","두 칸을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#22','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C6',3,'error','auto','「그림책이 곰을 봅니다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「그림책이 곰을 봅니다.」 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 곰이 그림책을 봅니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「봅니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「그림책」을 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["보는 것은 곰이에요.","누가(곰이) 무엇을(그림책을) 어찌하다(봅니다)로 고쳐요.","32쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#23','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C3',4,'sa','auto','「내 마음이 꽁꽁, 얼음처럼 꽁꽁!」이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「내 마음이 꽁꽁, 얼음처럼 꽁꽁!」이 나타내는 마음을 한 낱말로 쓰세요.","answer":["떨려요","떨려","떨렸어요","떨렸어","떨린다","떨림","긴장","긴장돼요","긴장했어요","무서워요","무서워"],"explanation":["떨려서 노랫말이 떠오르지 않는 마음이에요.","신나거나 화난 마음이 아니에요.","첫 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#24','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C5',4,'essay','teacher','지도서 평가 — 아빠께서 생일 선물을 사 주셨을 때, 듣는 사람을 생각하며 「나는 (있었던 일) (내 기분).」으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"지도서 평가 — 아빠께서 생일 선물을 사 주셨을 때, 듣는 사람을 생각하며 「나는 (있었던 일) (내 기분).」으로 쓰세요.","answer_guide":{"answer":"예: 나는 아빠께서 생일 선물을 사 주셔서 행복했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","좋은 기분도 말로 전해요.","23쪽 5번이 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_a#25','kor',1,2,'u1','','g1_2_kor_u1_review_a','unit_review','K1-2-u1-C2',4,'essay','teacher','지도서 평가 — 공원 그림(바람개비·줄넘기·자전거)을 보고 떠오르는 흉내 내는 말을 넣어 문장을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"지도서 평가 — 공원 그림(바람개비·줄넘기·자전거)을 보고 떠오르는 흉내 내는 말을 넣어 문장을 쓰세요.","answer_guide":{"answer":"예: 바람개비가 빙글빙글 돌아간다. / 줄넘기를 폴짝폴짝 넘는다. / 자전거가 씽씽 달린다. — 그림 상황에 어울리는 흉내 내는 말이면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","그림의 상황과 어울리는가","문장이 자연스러운가"]},"explanation":["빙글빙글·폴짝폴짝·씽씽처럼 상황에 어울리는 말을 넣어요.","상관없는 소리는 어긋나요.","그림을 먼저 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#1','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C1',1,'mc','auto','『국어』 10쪽 글에서 잎이 움직이는 모양을 흉내 낸 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 10쪽 글에서 잎이 움직이는 모양을 흉내 낸 말은?","options":[{"t":"살랑살랑","correct":true},{"t":"단풍나무","mis":"K1-2-u1-X01"},{"t":"움직입니다","mis":"K1-2-u1-X01"}],"explanation":["잎이 살랑살랑 움직여요.","단풍나무는 이름, 움직입니다는 하는 일이에요.","모양을 옮긴 말을 찾아요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#2','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C1',1,'mc','auto','다음 가운데 흉내 내는 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 흉내 내는 말은?","options":[{"t":"깡충깡충","correct":true},{"t":"토끼","mis":"K1-2-u1-X01"},{"t":"기뻐요","mis":"K1-2-u1-X01"}],"explanation":["깡충깡충은 토끼가 뛰는 모양이에요.","토끼는 이름, 기뻐요는 기분이에요.","모양이나 소리를 옮긴 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#3','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',1,'mc','auto','『국어』 20쪽 — 눈물을 흘리는 아이의 기분은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 20쪽 — 눈물을 흘리는 아이의 기분은?","options":[{"t":"슬퍼요","correct":true},{"t":"기뻐요","mis":"K1-2-u1-X07"},{"t":"화나요","mis":"K1-2-u1-X07"}],"explanation":["눈물을 흘리면 슬퍼요.","기쁘거나 화난 모습이 아니에요.","표정을 봐요."],"asset":{"type":"scene","icon":"😢"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#4','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',1,'mc','auto','『국어』 9쪽 — 병원에 누워 있는 장면에 어울리는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 9쪽 — 병원에 누워 있는 장면에 어울리는 말은?","options":[{"t":"걱정돼요","correct":true},{"t":"신나요","mis":"K1-2-u1-X07"},{"t":"뿌듯해요","mis":"K1-2-u1-X07"}],"explanation":["아프면 속상하고 걱정돼요.","신나거나 뿌듯한 일이 아니에요.","기분 나무를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
