INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#6','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은?',ARRAY['K1-2-u1-X09','K1-2-u1-X10']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은?","options":[{"t":"나는 네가 색연필을 빌려줘서 고마웠어.","correct":true},{"t":"너는 왜 이렇게 늦게 줘?","mis":"K1-2-u1-X09"},{"t":"됐어, 필요 없어.","mis":"K1-2-u1-X10"}],"explanation":["「나」로 시작해 고마운 마음을 말했어요.","탓하거나 밀어내는 말이 아니에요.","『국어』 23쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#7','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C6',1,'mc','auto','『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?","options":[{"t":"곰이 모자를 벗습니다.","correct":true},{"t":"모자가 곰을 벗습니다.","mis":"K1-2-u1-X13"},{"t":"곰이 모자를 마십니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(곰이) 무엇을(모자를) 어찌하다(벗습니다)예요.","모자가 곰을 벗을 수 없고, 모자를 마실 수도 없어요.","낱말을 따라가요."],"asset":{"type":"scene","icon":"🐻🧢"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#8','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C3',1,'mc','auto','「내 마음이 반짝반짝, 보석처럼 반짝반짝!」이 나타내는 마음은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음이 반짝반짝, 보석처럼 반짝반짝!」이 나타내는 마음은?","options":[{"t":"신나요","correct":true},{"t":"떨려요","mis":"K1-2-u1-X06"},{"t":"화나요","mis":"K1-2-u1-X06"}],"explanation":["나만 뜀틀에 올라 신난 마음이에요.","떨린 마음은 꽁꽁이에요.","두 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#9','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C1',2,'match','auto','『국어』 11쪽 — 그림과 어울리는 흉내 내는 말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"『국어』 11쪽 — 그림과 어울리는 흉내 내는 말을 이어 보세요.","pairs":[{"l":"😆 웃는 아이","r":"깔깔"},{"l":"☁️ 구름","r":"둥실둥실"},{"l":"🕰️ 시계","r":"째깍째깍"}],"mis":"K1-2-u1-X03","explanation":["웃는 아이는 깔깔, 구름은 둥실둥실이에요.","시계는 째깍째깍이에요.","그림을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#10','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C2',2,'mc','auto','『국어』 13쪽 — 훨씬 재미있는 문장은?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"『국어』 13쪽 — 훨씬 재미있는 문장은?","options":[{"t":"오리가 뒤뚱뒤뚱 걸어간다.","correct":true},{"t":"오리가 걸어간다.","mis":"K1-2-u1-X04"},{"t":"오리가 빨리 걸어간다.","mis":"K1-2-u1-X04"}],"explanation":["뒤뚱뒤뚱을 넣으면 오리 모습이 떠올라요.","흉내 내는 말이 없으면 모습이 그려지지 않아요.","교과서 13쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
