INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#12','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',2,'match','auto','『국어활동』 14~15쪽 — 상황과 그때의 기분을 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"『국어활동』 14~15쪽 — 상황과 그때의 기분을 이어 보세요.","pairs":[{"l":"회전목마를 탔을 때","r":"신났어요"},{"l":"달리기에서 일 등을 했을 때","r":"뿌듯했어요"},{"l":"친구가 만든 성을 망가뜨렸을 때","r":"미안했어요"}],"mis":"K1-2-u1-X07","explanation":["회전목마는 신나고, 일 등은 뿌듯해요.","성을 망가뜨리면 미안해요.","기차 그림을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
