INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#14','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',2,'mc','auto','『국어』 22쪽 — 솔직한 내 기분을 생각한 다음 할 일은?',ARRAY['K1-2-u1-X11','K1-2-u1-X09']::text[],false,'{"seq":14,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 22쪽 — 솔직한 내 기분을 생각한 다음 할 일은?","options":[{"t":"솔직하게 말했을 때 듣는 사람의 기분을 생각해 본다","correct":true},{"t":"큰 소리로 연습한다","mis":"K1-2-u1-X11"},{"t":"친구 잘못을 세어 본다","mis":"K1-2-u1-X09"}],"explanation":["듣는 사람의 기분을 생각해요.","연습이나 잘못 세기는 차례에 없어요.","네 단계의 세 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
