INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#16','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C3',2,'ox','auto','「우르릉 쾅쾅」은 신나는 마음을 나타내요.',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":16,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"「우르릉 쾅쾅」은 신나는 마음을 나타내요.","answer":"X","reason_options":[{"t":"성이 무너져 화가 난 마음을 나타내니까","correct":true},{"t":"우르릉 쾅쾅은 즐거운 소리니까","mis":"K1-2-u1-X06"}],"mis":"K1-2-u1-X06","explanation":["우르릉 쾅쾅은 화산처럼 화난 마음이에요.","신난 마음은 반짝반짝이에요.","네 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
