INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#18','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C2',3,'error','auto','「빗방울이 반짝반짝 떨어졌다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「빗방울이 반짝반짝 떨어졌다.」 무엇이 잘못되었나요?","options":[{"t":"반짝반짝은 빛나는 모양이라 빗방울과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"빗방울에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「떨어졌다」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["빗방울은 후드득이에요.","반짝반짝은 별이에요.","19쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#19','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C4',3,'ox','auto','『국어』 31쪽 — 「듣는 사람의 기분을 생각하며 말한다」는 알맞은 방법이에요.',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"『국어』 31쪽 — 「듣는 사람의 기분을 생각하며 말한다」는 알맞은 방법이에요.","answer":"O","reason_options":[{"t":"배려하며 말해야 마음이 잘 전해지니까","correct":true},{"t":"듣는 사람 기분은 상관없으니까","mis":"K1-2-u1-X07"}],"mis":"K1-2-u1-X07","explanation":["듣는 사람의 기분을 생각하며 말해요.","그래야 상처 주지 않고 마음이 전해져요.","31쪽 관람차에서 색칠하는 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#20','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',3,'mc','auto','「화내지 말고 예쁘게 말해요」 — 도치가 구름을 없앤 방법은?',ARRAY['K1-2-u1-X09','K1-2-u1-X15']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"「화내지 말고 예쁘게 말해요」 — 도치가 구름을 없앤 방법은?","options":[{"t":"바르고 고운 말로 예쁘게 말했어요","correct":true},{"t":"더 크게 화를 냈어요","mis":"K1-2-u1-X09"},{"t":"구름을 손으로 밀었어요","mis":"K1-2-u1-X15"}],"explanation":["「얘들아, 난 너희들이랑 함께 놀면 좋겠어.」라고 말하자 구름이 감쪽같이 사라졌어요.","화를 내면 커져요.","25쪽 내용 알기 (3)이에요."],"asset":{"type":"passage","lines":["도치는 화를 내며 말하는 버릇이 있어서 별명이 버럭쟁이예요.","어느 날 도치 머리 위에 손바닥만 한 구름이 생겼어요.","도치가 버럭버럭 소리를 지르고 치치에게도 화를 내자 구름은 그림책만 하게 커졌어요. 번쩍! 우르르 쾅!","도치가 펑펑 울자 양산을 쓴 할머니가 나타나 나쁜 말 구름을 없애는 방법을 소곤소곤 알려 주었어요.","놀이터에서 도치는 화가 났지만 할머니 말씀을 떠올려 말했어요. \"얘들아, 난 너희들이랑 함께 놀면 좋겠어.\"","친구들과 사이좋게 놀 수 있어서 도치는 무척 기뻤고, 구름은 감쪽같이 사라졌어요."],"title":"화내지 말고 예쁘게 말해요 (글 안미연·그림 서희정) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#21','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',3,'error','auto','「나는 화가 났어.」 이 말에는 무엇이 빠졌나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 화가 났어.」 이 말에는 무엇이 빠졌나요?","options":[{"t":"무슨 일이 있었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」이 빠졌어요","mis":"K1-2-u1-X09"},{"t":"말이 너무 길어요","mis":"K1-2-u1-X11"}],"explanation":["왜 화가 났는지 있었던 일을 말해야 해요.","「나는 성이 무너져서 화가 났어」처럼 채워요.","22쪽 주영이의 말을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#22','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C6',3,'error','auto','「모자가 곰을 벗습니다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「모자가 곰을 벗습니다.」 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 곰이 모자를 벗습니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「벗습니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「곰」을 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["벗는 것은 곰이에요.","누가(곰이) 무엇을(모자를) 어찌하다(벗습니다)로 고쳐요.","32쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#23','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C3',4,'sa','auto','「내 마음이 반짝반짝, 보석처럼 반짝반짝!」이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「내 마음이 반짝반짝, 보석처럼 반짝반짝!」이 나타내는 마음을 한 낱말로 쓰세요.","answer":["신나요","신나","신났어요","신났어","신남","기뻐요","기뻐","기뻤어요","기쁨","즐거워요","즐거워","즐거웠어요","행복해요","뿌듯해요","뿌듯해"],"explanation":["나만 뜀틀에 올라 신난 마음이에요.","떨리거나 화난 마음이 아니에요.","두 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#24','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C5',4,'essay','teacher','지도서 평가 — 친구가 색연필을 빌려주었을 때, 듣는 사람을 생각하며 「나는 (있었던 일) (내 기분).」으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"지도서 평가 — 친구가 색연필을 빌려주었을 때, 듣는 사람을 생각하며 「나는 (있었던 일) (내 기분).」으로 쓰세요.","answer_guide":{"answer":"예: 나는 친구가 색연필을 빌려줘서 고마웠어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","고마운 마음을 말로 전해요.","23쪽 5번이 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_b#25','kor',1,2,'u1','','g1_2_kor_u1_review_b','unit_review','K1-2-u1-C2',4,'essay','teacher','『국어활동』 11쪽 — 「윙윙」을 넣어 짧은 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"『국어활동』 11쪽 — 「윙윙」을 넣어 짧은 글을 쓰세요.","answer_guide":{"answer":"예: 꿀벌이 윙윙 소리를 내며 날고 있다. / 찬 바람이 윙윙 지나갔다. — 윙윙과 어울리면 맞아요.","scoring_points":["윙윙이 들어갔는가","벌·바람 같은 상황과 어울리는가","문장이 자연스러운가"]},"explanation":["윙윙은 벌이나 바람 소리예요.","「첨벙첨벙 물놀이를 했다」처럼 써요.","국어활동 보기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#1','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C1',1,'mc','auto','『국어』 10쪽 글에서 고양이 소리를 흉내 낸 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 10쪽 글에서 고양이 소리를 흉내 낸 말은?","options":[{"t":"야옹","correct":true},{"t":"고양이","mis":"K1-2-u1-X01"},{"t":"반겨","mis":"K1-2-u1-X01"}],"explanation":["고양이들이 야옹 소리를 내요.","고양이는 이름이에요.","소리를 옮긴 말을 찾아요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#2','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C1',1,'mc','auto','다음 가운데 흉내 내는 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":2,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 흉내 내는 말은?","options":[{"t":"째깍째깍","correct":true},{"t":"시계","mis":"K1-2-u1-X01"},{"t":"즐거워요","mis":"K1-2-u1-X01"}],"explanation":["째깍째깍은 시계 소리예요.","시계는 이름, 즐거워요는 기분이에요.","소리를 옮긴 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#3','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',1,'mc','auto','『국어』 20쪽 — 팔짱 끼고 씩씩대는 아이의 기분은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":3,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 20쪽 — 팔짱 끼고 씩씩대는 아이의 기분은?","options":[{"t":"화나요","correct":true},{"t":"무서워요","mis":"K1-2-u1-X07"},{"t":"기뻐요","mis":"K1-2-u1-X07"}],"explanation":["씩씩대는 모습은 화나요.","무섭거나 기쁜 모습이 아니에요.","몸짓을 봐요."],"asset":{"type":"scene","icon":"😠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#4','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',1,'mc','auto','『국어』 9쪽 — 선물을 받는 장면에 어울리는 말은?',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":4,"concept":"K1-2-u1-C4","difficulty":1,"kind":"mc","stem":"『국어』 9쪽 — 선물을 받는 장면에 어울리는 말은?","options":[{"t":"고마워요","correct":true},{"t":"화나요","mis":"K1-2-u1-X07"},{"t":"심심해요","mis":"K1-2-u1-X07"}],"explanation":["선물을 받으면 기쁘고 고마워요.","화나거나 심심한 일이 아니에요.","기분 나무를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
