INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#6','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은?","options":[{"t":"나는 내 책이 우유에 젖어서 많이 속상했어.","correct":true},{"t":"너 때문에 책 다 망쳤잖아!","mis":"K1-2-u1-X09"},{"t":"저리 가!","mis":"K1-2-u1-X09"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말했어요.","탓하거나 밀어내는 말이 아니에요.","『국어』 27쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#7','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C6',1,'mc','auto','『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?","options":[{"t":"곰이 우유를 마십니다.","correct":true},{"t":"우유가 곰을 마십니다.","mis":"K1-2-u1-X13"},{"t":"곰이 우유를 벗습니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(곰이) 무엇을(우유를) 어찌하다(마십니다)예요.","우유가 곰을 마실 수 없고, 우유를 벗을 수도 없어요.","낱말을 따라가요."],"asset":{"type":"scene","icon":"🐻🥛"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#8','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C3',1,'mc','auto','「내 마음이 찌지직, 번개처럼 찌지직!」이 나타내는 마음은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음이 찌지직, 번개처럼 찌지직!」이 나타내는 마음은?","options":[{"t":"깜짝 놀랐어요","correct":true},{"t":"신나요","mis":"K1-2-u1-X06"},{"t":"편안해요","mis":"K1-2-u1-X06"}],"explanation":["민호가 달려들어 깜짝 놀란 마음이에요.","신난 마음은 반짝반짝이에요.","세 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#9','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C1',2,'match','auto','『국어』 12쪽 — 그림과 어울리는 흉내 내는 말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"『국어』 12쪽 — 그림과 어울리는 흉내 내는 말을 이어 보세요.","pairs":[{"l":"🌼 꽃","r":"활짝"},{"l":"🪲 매미","r":"맴맴"},{"l":"🐥 병아리","r":"삐악삐악"}],"mis":"K1-2-u1-X03","explanation":["꽃은 활짝, 매미는 맴맴이에요.","병아리는 삐악삐악이에요.","보기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#10','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C2',2,'mc','auto','『국어』 8쪽 — 더 실감 나는 문장은?',ARRAY['K1-2-u1-X04']::text[],false,'{"seq":10,"concept":"K1-2-u1-C2","difficulty":2,"kind":"mc","stem":"『국어』 8쪽 — 더 실감 나는 문장은?","options":[{"t":"친구가 활짝 웃고 있어요.","correct":true},{"t":"친구가 웃고 있어요.","mis":"K1-2-u1-X04"},{"t":"친구가 조금 웃고 있어요.","mis":"K1-2-u1-X04"}],"explanation":["활짝을 넣으면 웃는 모습이 떠올라요.","흉내 내는 말이 없으면 어떻게 웃는지 몰라요.","교과서 8쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
