INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#12','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',2,'match','auto','『국어』 30쪽 — 상황과 그때의 기분을 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"K1-2-u1-C4","difficulty":2,"kind":"match","stem":"『국어』 30쪽 — 상황과 그때의 기분을 이어 보세요.","pairs":[{"l":"진수가 준비물을 빌려줬을 때","r":"고마웠어"},{"l":"지수가 병원에 입원했을 때","r":"걱정했어"},{"l":"민지가 함께 놀자고 말해 줬을 때","r":"기뻤어"}],"mis":"K1-2-u1-X07","explanation":["빌려주면 고맙고, 입원하면 걱정돼요.","함께 놀자고 하면 기뻐요.","30쪽 2번 친구들의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
