INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#14','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',2,'mc','auto','『국어』 22쪽 — 네 단계의 마지막은?',ARRAY['K1-2-u1-X09','K1-2-u1-X12']::text[],false,'{"seq":14,"concept":"K1-2-u1-C5","difficulty":2,"kind":"mc","stem":"『국어』 22쪽 — 네 단계의 마지막은?","options":[{"t":"「나」라는 말로 시작하며 정리한 생각을 말한다","correct":true},{"t":"「너」로 시작하며 말한다","mis":"K1-2-u1-X09"},{"t":"기분은 말하지 않는다","mis":"K1-2-u1-X12"}],"explanation":["「나」로 시작해 있었던 일과 기분을 말해요.","「너」로 시작하면 탓하는 말이 돼요.","네 단계의 네 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
