INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#16','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C3',2,'ox','auto','「꽁꽁」은 떨려서 굳은 마음을 나타내요.',ARRAY['K1-2-u1-X05']::text[],false,'{"seq":16,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"「꽁꽁」은 떨려서 굳은 마음을 나타내요.","answer":"O","reason_options":[{"t":"얼음처럼 꽁꽁 얼어 노랫말이 안 떠오르는 마음이니까","correct":true},{"t":"꽁꽁은 추운 날씨만 나타내니까","mis":"K1-2-u1-X05"}],"mis":"K1-2-u1-X05","explanation":["첫 장면에서 떨린 마음을 꽁꽁으로 나타냈어요.","날씨만 나타내는 게 아니에요.","첫 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
