INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#18','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C2',3,'error','auto','「유리창이 살금살금 깨졌다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「유리창이 살금살금 깨졌다.」 무엇이 잘못되었나요?","options":[{"t":"살금살금은 조용히 걷는 모양이라 깨지는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"유리창에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「깨졌다」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["유리창은 쨍그랑 깨져요.","살금살금은 고양이가 걷는 모양이에요.","30쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#19','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C4',3,'ox','auto','『국어』 31쪽 — 「자신의 기분을 화내며 말한다」는 알맞은 방법이에요.',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"『국어』 31쪽 — 「자신의 기분을 화내며 말한다」는 알맞은 방법이에요.","answer":"X","reason_options":[{"t":"화내며 말하면 도치처럼 나쁜 말 구름이 커지니까","correct":true},{"t":"화를 내야 기분이 잘 전해지니까","mis":"K1-2-u1-X09"}],"mis":"K1-2-u1-X09","explanation":["화내며 말하면 듣는 사람이 상처받아요.","「나」로 시작해 솔직하게 말해요.","31쪽에서 색칠하지 않는 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#20','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',3,'mc','auto','『국어활동』 9쪽 글 — ㉠에 알맞은 흉내 내는 말은?',ARRAY['K1-2-u1-X03']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"『국어활동』 9쪽 글 — ㉠에 알맞은 흉내 내는 말은?","options":[{"t":"휘휘","correct":true},{"t":"방긋","mis":"K1-2-u1-X03"},{"t":"어흥","mis":"K1-2-u1-X03"}],"explanation":["코끼리가 코를 휘휘 휘저어요.","방긋은 웃는 모양, 어흥은 호랑이 소리예요.","보기(방긋·어흥·휘휘·대롱대롱)를 떠올려요."],"asset":{"type":"passage","lines":["동물원으로 현장 체험 학습을 갔습니다. 동물들이 반갑다고 웃으며 인사를 합니다.","코끼리가 코를 ㉠ 휘저으며 우리를 반겨 줍니다. 그러자 곰도 ㉡ 웃는 것 같습니다.","원숭이는 나무에 ㉢ 매달리며 인사합니다. 호랑이는 ㉣ 소리를 냅니다."],"title":"국어활동 9쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#21','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',3,'error','auto','「나는 너 같은 애랑 안 놀아.」 「나」로 시작했는데 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 너 같은 애랑 안 놀아.」 「나」로 시작했는데 무엇이 잘못되었나요?","options":[{"t":"있었던 일과 내 기분 대신 상대를 밀어내는 말을 넣었어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나는」을 빼야 해요","mis":"K1-2-u1-X09"},{"t":"더 크게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["밀어내는 말이면 마음이 전해지지 않아요.","도치의 「저리 가!」와 같은 말이에요.","「나는 ○○해서 ○○했어」로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#22','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C6',3,'error','auto','「우유가 곰을 마십니다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「우유가 곰을 마십니다.」 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 곰이 우유를 마십니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「마십니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「우유」를 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["마시는 것은 곰이에요.","누가(곰이) 무엇을(우유를) 어찌하다(마십니다)로 고쳐요.","32쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#23','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C3',4,'sa','auto','「내 마음이 찌지직, 번개처럼 찌지직!」이 나타내는 마음을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「내 마음이 찌지직, 번개처럼 찌지직!」이 나타내는 마음을 쓰세요.","answer":["깜짝놀랐어요","놀랐어요","놀라요","놀랐어","깜짝놀라요","깜짝놀랐어","놀람","놀라다","놀랐다","깜짝"],"explanation":["민호가 달려들어 깜짝 놀란 마음이에요.","신나거나 편안한 마음이 아니에요.","세 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#24','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C5',4,'essay','teacher','지도서 평가 — 동생이 내 옷에 우유를 쏟았을 때, 듣는 사람을 생각하며 「나는 (있었던 일) (내 기분).」으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"지도서 평가 — 동생이 내 옷에 우유를 쏟았을 때, 듣는 사람을 생각하며 「나는 (있었던 일) (내 기분).」으로 쓰세요.","answer_guide":{"answer":"예: 나는 옷이 젖어서 속상했어. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["「나는 ○○해서 ○○했어」 틀에 맞춰요.","「너 때문에」 대신 젖은 일을 말해요.","27쪽이 본보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_c#25','kor',1,2,'u1','','g1_2_kor_u1_review_c','unit_review','K1-2-u1-C2',4,'essay','teacher','『국어활동』 11쪽 — 「꾸벅꾸벅」을 넣어 짧은 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"『국어활동』 11쪽 — 「꾸벅꾸벅」을 넣어 짧은 글을 쓰세요.","answer_guide":{"answer":"예: 동생이 꾸벅꾸벅 졸고 있다. / 친척들에게 꾸벅꾸벅 인사했다. — 꾸벅꾸벅과 어울리면 맞아요.","scoring_points":["꾸벅꾸벅이 들어갔는가","조는 모습이나 인사하는 모습과 어울리는가","문장이 자연스러운가"]},"explanation":["꾸벅꾸벅은 조는 모양이나 인사하는 모양이에요.","상황을 먼저 떠올려요.","국어활동 보기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#1','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C1',1,'mc','auto','『국어』 10쪽 글에서 자전거가 지나가는 모습을 흉내 낸 말은?',ARRAY['K1-2-u1-X01']::text[],false,'{"seq":1,"concept":"K1-2-u1-C1","difficulty":1,"kind":"mc","stem":"『국어』 10쪽 글에서 자전거가 지나가는 모습을 흉내 낸 말은?","options":[{"t":"씽씽","correct":true},{"t":"자전거","mis":"K1-2-u1-X01"},{"t":"아이가","mis":"K1-2-u1-X01"}],"explanation":["자전거를 타고 씽씽 지나가요.","자전거·아이는 이름이에요.","빠른 모습을 옮긴 말을 찾아요."],"asset":{"type":"passage","lines":["가을 하늘에 구름이 둥실둥실 떠 있습니다.","단풍나무의 잎이 가을바람에 살랑살랑 움직입니다.","귀여운 고양이들이 야옹 소리를 내며 반겨 줍니다.","아이가 자전거를 타고 씽씽 지나갑니다."],"title":"국어 10쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
