INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#6','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',1,'mc','auto','듣는 사람을 생각한 말은?',ARRAY['K1-2-u1-X09']::text[],false,'{"seq":6,"concept":"K1-2-u1-C5","difficulty":1,"kind":"mc","stem":"듣는 사람을 생각한 말은?","options":[{"t":"얘들아, 난 너희들이랑 함께 놀면 좋겠어.","correct":true},{"t":"너희 다 미워!","mis":"K1-2-u1-X09"},{"t":"저리 가! 귀찮단 말이야!","mis":"K1-2-u1-X09"}],"explanation":["도치가 예쁘게 말한 말이에요.","버럭버럭 화내는 말이 아니에요.","「화내지 말고 예쁘게 말해요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#7','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C6',1,'mc','auto','『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":7,"concept":"K1-2-u1-C6","difficulty":1,"kind":"mc","stem":"『국어』 32쪽 — 곰이 무엇을 할까요? 알맞은 문장은?","options":[{"t":"곰이 그림책을 삽니다.","correct":true},{"t":"그림책이 곰을 삽니다.","mis":"K1-2-u1-X13"},{"t":"곰이 그림책을 마십니다.","mis":"K1-2-u1-X14"}],"explanation":["누가(곰이) 무엇을(그림책을) 어찌하다(삽니다)예요.","그림책이 곰을 살 수 없고, 그림책을 마실 수도 없어요.","낱말을 따라가요."],"asset":{"type":"scene","icon":"🐻📖"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#8','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C3',1,'mc','auto','「내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!」이 나타내는 마음은?',ARRAY['K1-2-u1-X06']::text[],false,'{"seq":8,"concept":"K1-2-u1-C3","difficulty":1,"kind":"mc","stem":"「내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!」이 나타내는 마음은?","options":[{"t":"화나요","correct":true},{"t":"떨려요","mis":"K1-2-u1-X06"},{"t":"신나요","mis":"K1-2-u1-X06"}],"explanation":["성이 무너져 화가 난 마음이에요.","떨린 마음은 꽁꽁이에요.","네 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#9','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C1',2,'match','auto','「동물 농장」 — 동물과 소리를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u1-C1","difficulty":2,"kind":"match","stem":"「동물 농장」 — 동물과 소리를 이어 보세요.","pairs":[{"l":"🐔 암탉","r":"꼬꼬댁"},{"l":"🦆 거위","r":"꽥꽥"},{"l":"🐄 송아지","r":"음매"}],"mis":"K1-2-u1-X03","explanation":["암탉은 꼬꼬댁, 거위는 꽥꽥이에요.","송아지는 음매예요.","노래를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
