INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#16','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C3',2,'ox','auto','「찌지직」은 깜짝 놀란 마음을 나타내요.',ARRAY['K1-2-u1-X05']::text[],false,'{"seq":16,"concept":"K1-2-u1-C3","difficulty":2,"kind":"ox","stem":"「찌지직」은 깜짝 놀란 마음을 나타내요.","answer":"O","reason_options":[{"t":"번개처럼 깜짝 놀란 마음을 옮긴 말이니까","correct":true},{"t":"찌지직은 종이 찢는 소리뿐이니까","mis":"K1-2-u1-X05"}],"mis":"K1-2-u1-X05","explanation":["민호가 달려들어 놀란 마음을 찌지직으로 나타냈어요.","종이 소리만 나타내는 게 아니에요.","세 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
