INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#18','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C2',3,'error','auto','「구름이 야옹 떠 있습니다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X03','K1-2-u1-X04']::text[],false,'{"seq":18,"concept":"K1-2-u1-C2","difficulty":3,"kind":"error","stem":"「구름이 야옹 떠 있습니다.」 무엇이 잘못되었나요?","options":[{"t":"야옹은 고양이 소리라 구름이 떠 있는 장면과 어울리지 않아요","correct":true,"mis_target":"K1-2-u1-X03"},{"t":"구름에는 흉내 내는 말을 쓸 수 없어요","mis":"K1-2-u1-X04"},{"t":"「떠 있습니다」를 빼야 해요","mis":"K1-2-u1-X03"}],"explanation":["구름은 둥실둥실 떠 있어요.","야옹은 고양이 소리예요.","10쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#19','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C4',3,'ox','auto','같은 상황에서도 사람마다 느끼는 기분이 다를 수 있어요.',ARRAY['K1-2-u1-X07']::text[],false,'{"seq":19,"concept":"K1-2-u1-C4","difficulty":3,"kind":"ox","stem":"같은 상황에서도 사람마다 느끼는 기분이 다를 수 있어요.","answer":"O","reason_options":[{"t":"놀이공원에서 신나는 친구도 무서운 친구도 있으니까","correct":true},{"t":"같은 상황이면 기분도 꼭 같아야 하니까","mis":"K1-2-u1-X07"}],"mis":"K1-2-u1-X07","explanation":["사람마다 느끼는 기분은 다를 수 있어요.","기분에는 맞고 틀린 것이 없어요.","기분 나무 활동을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#20','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',3,'mc','auto','『국어활동』 9쪽 글 — ㉣에 알맞은 흉내 내는 말은?',ARRAY['K1-2-u1-X03']::text[],false,'{"seq":20,"concept":"K1-2-u1-C5","difficulty":3,"kind":"mc","stem":"『국어활동』 9쪽 글 — ㉣에 알맞은 흉내 내는 말은?","options":[{"t":"어흥","correct":true},{"t":"대롱대롱","mis":"K1-2-u1-X03"},{"t":"휘휘","mis":"K1-2-u1-X03"}],"explanation":["호랑이는 어흥 소리를 내요.","대롱대롱은 매달린 모양, 휘휘는 휘젓는 모양이에요.","보기를 떠올려요."],"asset":{"type":"passage","lines":["동물원으로 현장 체험 학습을 갔습니다. 동물들이 반갑다고 웃으며 인사를 합니다.","코끼리가 코를 ㉠ 휘저으며 우리를 반겨 줍니다. 그러자 곰도 ㉡ 웃는 것 같습니다.","원숭이는 나무에 ㉢ 매달리며 인사합니다. 호랑이는 ㉣ 소리를 냅니다."],"title":"국어활동 9쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#21','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',3,'error','auto','「나는 네가 쳐서 나쁜 애라고 생각했어.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X10','K1-2-u1-X09','K1-2-u1-X11']::text[],false,'{"seq":21,"concept":"K1-2-u1-C5","difficulty":3,"kind":"error","stem":"「나는 네가 쳐서 나쁜 애라고 생각했어.」 무엇이 잘못되었나요?","options":[{"t":"「나」로 시작했지만 내 기분 대신 상대를 나쁘다고 탓했어요","correct":true,"mis_target":"K1-2-u1-X10"},{"t":"「나」로 시작한 것이 잘못이에요","mis":"K1-2-u1-X09"},{"t":"더 길게 말해야 해요","mis":"K1-2-u1-X11"}],"explanation":["「나쁜 애」는 탓하는 말이에요.","「나는 성이 무너져서 속상했어」처럼 내 기분을 말해요.","22쪽을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#22','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C6',3,'error','auto','「노래가 베짱이를 부릅니다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u1-X13','K1-2-u1-X14']::text[],false,'{"seq":22,"concept":"K1-2-u1-C6","difficulty":3,"kind":"error","stem":"「노래가 베짱이를 부릅니다.」 무엇이 잘못되었나요?","options":[{"t":"누가와 무엇을 자리가 바뀌었어요 — 베짱이가 노래를 부릅니다","correct":true,"mis_target":"K1-2-u1-X13"},{"t":"「부릅니다」가 잘못이에요","mis":"K1-2-u1-X14"},{"t":"「노래」를 빼야 해요","mis":"K1-2-u1-X13"}],"explanation":["부르는 것은 베짱이예요.","누가(베짱이가) 무엇을(노래를) 어찌하다(부릅니다)로 고쳐요.","지도서 문장 만들기 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#23','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C3',4,'sa','auto','「내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!」이 나타내는 마음을 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u1-C3","difficulty":4,"kind":"sa","stem":"「내 마음이 우르릉 쾅쾅, 화산처럼 우르릉 쾅쾅!」이 나타내는 마음을 한 낱말로 쓰세요.","answer":["화나요","화나","화났어요","화났어","화가나요","화가났어요","화","화남","화가난다","화난다","화가났다","속상해요","속상해"],"explanation":["성이 무너져 화가 난 마음이에요.","떨리거나 신난 마음이 아니에요.","네 번째 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#24','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C5',4,'essay','teacher','「너 때문에 성이 무너졌잖아!」를 듣는 사람을 생각하며 「나」로 시작하는 말로 바꿔 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u1-C5","difficulty":4,"kind":"essay","stem":"「너 때문에 성이 무너졌잖아!」를 듣는 사람을 생각하며 「나」로 시작하는 말로 바꿔 쓰세요.","answer_guide":{"answer":"예: 나는 내가 만든 성이 무너져서 정말 속상해. — 「나」로 시작 + 있었던 일 + 기분이면 맞아요.","scoring_points":["「나」로 시작했는가","있었던 일이 들어 있는가","기분 말이 있고 탓하는 말이 없는가"]},"explanation":["22쪽 주영이의 말이 본보기예요.","「너 때문에」 대신 성이 무너진 일을 말해요.","첫 낱말을 「나」로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u1_review_d#25','kor',1,2,'u1','','g1_2_kor_u1_review_d','unit_review','K1-2-u1-C2',4,'essay','teacher','『국어활동』 10쪽 — 「새싹이 ___.」 흉내 내는 말을 넣어 문장을 완성해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u1-C2","difficulty":4,"kind":"essay","stem":"『국어활동』 10쪽 — 「새싹이 ___.」 흉내 내는 말을 넣어 문장을 완성해 쓰세요.","answer_guide":{"answer":"예: 새싹이 쑥쑥 크고 있다. / 새싹이 파릇파릇 돋아난다. — 새싹과 어울리면 맞아요.","scoring_points":["흉내 내는 말이 들어갔는가","새싹이 자라는 모습과 어울리는가","문장이 자연스러운가"]},"explanation":["쑥쑥·파릇파릇처럼 자라는 모양을 넣어요.","「사과가 주렁주렁 열렸다」처럼 써요.","사진을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
